programs.haiku:
READS = ()
"""Negative on punctuation and small function words that follow a run of capitalized words.

Layer-0 MLP component (layers.0.mlp.down_proj, unit 4992). Its activation is most
negative on a comma, opening parenthesis or dash right after a name-like run of
capitalized words, e.g. "...Air Force History and Museums Program," or
"Take A Girl Like You (song)". The longer the run, the more negative: a comma after
one capitalized word is about -0.8, after three or more about -1.6, and after a
lowercase word about -0.4. A lone capitalized word that starts a sentence ("However,")
does not count as a name, and a comma after reasoning words ("if", "then", "however")
is a little less negative. Common function words right after a name ("and", "in",
"is", "for") get a smaller negative value. Everything else predicts 0.
"""

# Punctuation: value with no name word before it, and added per capitalized word.
BASE = {',': -0.4, ' (': -0.2, '),': -0.45, '，': -0.25, ' —': -0.2, '.': 0.0, ')': -0.05,
        ' and': 0.0, ' in': 0.0}
PER_WORD = {',': -0.45, ' (': -0.4, '),': -0.45, '，': -0.4, ' —': -0.4, '.': -0.2, ')': -0.25,
            ' and': -0.25, ' in': -0.25}
# Function words that, after a name, are mildly negative (value per name word).
AFTER_NAME = {' is', ' for', ' was', ' at', ' from', ' by', ' or', ' to', ' with', ' that', ' has', ' had', ' as'}
# Small words allowed inside a name ("Bank of America").
NAME_LINKS = {'of', 'the', 'and', 'de', 'for', '&', 'la', 'von', 'van', 'du', 'in', 'at', 'on', 'der', 'y'}
# Reasoning words: a comma after them is less negative.
REASON = {'if', 'then', 'however', 'so', 'but', 'case', 'example', 'no', 'each', 'when',
          'is', 'are', 'be', 'this', 'that', 'not', 'only', 'would', '='}


def _is_cap(word):
    word = word.strip('"\'([{“‘')
    return len(word) > 0 and word[0].isupper()


def _name_run(words):
    """How many capitalized words end the text, allowing one small link word inside."""
    run, skipped, i = 0, 0, len(words) - 1
    while i >= 0:
        if _is_cap(words[i]):
            run, skipped = run + 1, 0
        elif words[i].strip().lower() in NAME_LINKS and run > 0 and skipped < 1:
            skipped += 1
        else:
            break
        i -= 1
    # A lone capitalized word that starts a sentence is not a name.
    if run == 1 and (len(words) == 1 or words[-2][-1:] in '.!?:\n'):
        run = 0
    return run


def step(carry, prefix, upstream):
    text = carry or ''
    if len(prefix.document_ids) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        text = ''
    tok = prefix.token_strings[-1]
    value = 0.0
    words = text.split()
    run = min(_name_run(words), 3)
    if tok in BASE:
        value = BASE[tok] + PER_WORD[tok] * run
    elif tok in AFTER_NAME:
        value = -0.15 * run
    if tok == ',':
        value += 0.15 * min(sum(w.strip().lower() in REASON for w in words[-10:]), 2)
    return (text + tok)[-80:], value

"""Hyphen joining a word: fires on a hyphen glued to the word before it."""
READS = ()

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if not tok.startswith("-"):
        return None, 0.0
    before = prefix.token_strings[-2] if len(prefix) > 1 else " "
    if not before or before[-1].isspace() or not before[-1].isalnum():
        return None, 0.0
    body = tok[1:]
    if body == "":
        return None, 0.9
    if not any(c.isalnum() for c in body):
        return None, 0.0
    if body.isupper():
        return None, 1.6
    if body.isdigit():
        return None, 1.2
    if len(body) == 1:
        return None, 1.5
    if len(body) == 2:
        return None, 1.0
    return None, 0.6

programs.sol:
"""Approximate a six-related signal and document/chat opening effects.

Recognize 6/fullwidth ６, selected English six-number words, Chinese 六,
and June (the sixth month). Adjust digit six using the preceding token's
character class and distance from document start. Chat boundaries have
separate opening responses. Ordinary starting punctuation, digits, capitalized
fragments and function words get negative corrections. Other tokens get zero.
These compact rules omit smaller token-specific affinities.
"""
import math

READS = ()
FUNCTION_WORDS = frozenset('''
the a an of in to on at by for with from as and or but if that this it is are
was were be not he she they we you his her their which who into out up down
'''.split())
CHAT_OPENING = {'user': 1.54, 'system': 1.82, 'assistant': 1.29}
TOOL_BOUNDARIES = {
    '<tool_call>': (1.08, -0.108),
    '</tool_call>': (1.22, -0.025),
    '</tool_response>': (1.22, 0.15),
}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    position, previous = (0, '') if carry is None or carry[0] != doc else (
        carry[1] + 1, carry[2])
    spelling = token.strip()
    word = spelling.lstrip('-').lower()
    value = 0.0
    if token in ('6', '６'):
        if position == 0:
            value = 0.705
        else:
            base = 0.60
            if previous.isdecimal():
                base = 0.57 if previous in ('0', '6') else (
                    0.62 if previous == '9' else 0.67)
            elif previous[-1:].isalpha() or previous.endswith('_'):
                base = 0.76
            elif previous == '-' or previous.strip() == '/':
                base = 0.65
            elif previous.strip() and all(
                    c in '+-=^<>×−≈*' for c in previous.strip()):
                base = 0.55
            value = base + 0.15 / math.sqrt(position + 1)
    elif word in ('six', 'sixth', 'sixty', 'sixteen'):
        value = 0.52 if word == 'sixteen' else 0.73
    elif word in ('六', '第六'):
        value = 0.96
    elif word == 'june':
        value = 0.27
    elif token == '<|im_start|>':
        value = 1.72 if position == 0 else -0.02
    elif previous == '<|im_start|>' and token in CHAT_OPENING:
        value = CHAT_OPENING[token] if position == 1 else (
            4.0 / (position + 4) if token == 'user' else 0.0)
    elif token == '<|im_end|>':
        value = 0.65 if position == 0 else (
            (0.03 if previous.startswith('</tool') else -0.24)
            + 2.0 / (position + 1))
    elif token in TOOL_BOUNDARIES:
        initial, ordinary = TOOL_BOUNDARIES[token]
        value = initial if position == 0 else ordinary
        if position and token.startswith('</'):
            value += 1.8 / (position + 1)
    elif position == 0 and token == '#':
        value = 0.807
    elif token.startswith(' ') and word in FUNCTION_WORDS:
        if position == 0:
            value = -0.395 if word == 'the' else -0.18
        else:
            value = -0.09 / (position + 1)**0.8
    elif position == 0:
        if not spelling:
            value = -0.071
        elif spelling.isdecimal():
            value = -0.129
        elif all(c in '(){}[],:;.!?，。' for c in spelling):
            value = -0.28
        elif all(not c.isalnum() for c in spelling):
            value = -0.167
        elif spelling[0].isupper():
            value = -0.184 if len(word) == 1 else -0.107
    return (doc, position, token), float(value)

programs.haiku:
"""Digit-six and chat-start detector (layers.0.mlp.down_proj:4994).

What it does, in plain terms:
  1. Fires on the digit 6 (and on the spelled-out or other written forms of six):
     the activation is about 0.65 on "6" and about 0.7 on "six", "sixth", "６", "六", ...
  2. Fires strongly on the chat-template opener "<|im_start|>" when it begins a document
     (first token of a row, or right after a document break): about 1.7.
  3. Fires on "user" when it directly follows that document-opening "<|im_start|>": about 1.5.
  Everything else is about 0 (the component is quiet on ordinary text).

The program reads only the tokens so far (no carry needed).
"""

READS = ()

DIGIT_SIX = {"6", "６", "六"}
WORD_SIX = {"six", "Six", " six", " Six", "sixth", " sixth", "Sixth", " Sixth",
            "sixty", " sixty", "sixteen", " sixteen", "-six", "-sixth"}


def _opens_document(prefix, i):
    """True if token i is the first token of its document within the row."""
    return i == 0 or prefix.document_ids[i - 1] != prefix.document_ids[i]


def step(carry, prefix, upstream):
    t = prefix.position
    tok = prefix.token_strings[t]
    if tok in DIGIT_SIX:
        return carry, 0.65
    if tok in WORD_SIX:
        return carry, 0.7
    if tok == "<|im_start|>" and _opens_document(prefix, t):
        return carry, 1.7
    if tok == "user" and t > 0 and prefix.token_strings[t - 1] == "<|im_start|>":
        if _opens_document(prefix, t - 1):
            return carry, 1.55
    return carry, 0.0

programs.sol:
"""A lexical detector centered on the word 'first'.

Predict a strong negative response to English 'first', adjusted for case,
code punctuation and a preceding 'the'. Recognize compounds, spelling
endings, and the continuation 'first of'. Translated first-position words
and related sequence/event words receive weaker negative responses.
Other tokens are predicted as zero; their weak fluctuations are omitted.
The amplitudes were calibrated on training activations.
"""
READS = ()

# First-position words and roots: German, Romance, Slavic, Scandinavian,
# Arabic, Japanese and Korean. Partial roots accommodate token boundaries.
FIRST_WORDS = {
    'erst': -1.6,
    'erste': -3.4, 'ersten': -3.8, 'erster': -3.5, 'erstes': -3.5,
    'premier': -1.1, 'première': -2.35, 'premiere': -1.4,
    'primer': -2.0, 'primero': -3.7, 'primera': -2.85,
    'primeiro': -4.2, 'primeira': -3.8,
    'prima': -2.05, 'primo': -1.7,
    'pierws': -3.8, 'første': -3.2,
    'перв': -3.0, 'первый': -2.4, 'первого': -3.6,
    'первой': -2.9, 'первых': -4.0,
    'الأول': -1.4, 'الأولى': -1.3,
    'まず': -3.25, 'まずは': -2.8, '初めて': -2.6,
    '처음': -1.65, '먼저': -2.0,
}
INITIAL_EVENT = {
    'debut': -0.95, 'debuted': -1.4, 'premiered': -1.65,
    'earliest': -0.95, 'foremost': -1.45, 'inaugural': -1.35,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    # Code punctuation can be part of the same token as an ordinal word.
    bare = word.lstrip('._-([,')
    lower = bare.lower()
    previous = ''
    if (prefix.position and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2].strip().lower()

    value = 0.0
    if lower == 'first':
        if bare.isupper():
            value = -7.25 if token.startswith(' ') else -6.5
        elif bare[0].isupper():
            value = -7.65 if token.startswith(' ') else -6.7
            if previous == 'the':
                value += 0.5
        elif token == ' first':
            value = -5.32 if previous == 'the' else -6.07
        elif word.startswith('('):
            value = -4.1
        else:
            value = -6.1
    elif lower == 'of' and previous == 'first':
        # Beginning of 'first of all'; the following word is not consulted.
        capitalized = prefix.token_strings[-2].strip()[0].isupper()
        value = -3.35 if capitalized else -1.55
    elif lower in ('ly', 's') and previous == 'first':
        value = -2.7
    elif lower in ('irst', 'rst'):
        # Spelling endings can fire even in unrelated words like 'thirsty'.
        value = -4.35 if bare.isupper() else (-2.8 if lower == 'irst' else -1.8)
    elif lower == 'firstly':
        value = -6.05 if bare[0].isupper() else -4.1
    elif lower.startswith('first'):
        # Given-name fields and other compounds dilute the response.
        value = -3.2
    elif lower == 'isfirst':
        value = -4.4
    elif lower in FIRST_WORDS:
        value = FIRST_WORDS[lower]
    elif word in ('第一', '首先', '的第一'):
        value = -4.4
    elif word == '第一个':
        value = -5.1
    elif '第一' in word:
        value = -3.3 if len(word) == 3 else -2.5
    elif word == '首':
        value = -1.95
    elif word in ('首次', '首要', '首个', '首款', '首批'):
        value = -3.1
    elif word in ('首位', '首轮'):
        value = -2.05
    elif word in ('先', '第'):
        value = -0.65
    elif lower in INITIAL_EVENT:
        value = INITIAL_EVENT[lower]
    elif lower == 'next':
        value = -0.9 if bare[0].isupper() else -0.58
    elif lower == 'last':
        value = -0.64 if bare[0].isupper() else -0.47
    elif lower == 'second':
        value = -0.95 if bare[0].isupper() else -0.2
    elif lower == 'secondly':
        value = -1.4
    elif lower == 'third' and bare[0].isupper():
        value = -0.57
    elif lower in ('prime', 'prim'):
        value = -0.9 if bare[0].isupper() else -0.6
    return None, value

programs.haiku:
"""Draft 1: fires on words about work, employment, pay and claims."""

READS = ()

PAY = {"pay", "paid", "payment", "payments", "salary", "wage", "wages"}
PEOPLE_AT_WORK = {"employer", "employers", "employee", "employees", "employ", "employment",
                  "staff", "worker", "workers", "work", "job", "jobs", "supervisor"}
CLAIMS = {"claim", "claims", "charge", "charges", "complaint", "complaints", "injury",
          "injuries", "strike", "strikes", "subcontract"}
WORDS = PAY | PEOPLE_AT_WORK | CLAIMS


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return None, 1.0 if word in WORDS else 0.0

programs.sol:
"""Predict a large spike on the explicit end-of-text separator, plus smaller
lexical responses. Other dialogue delimiters have their own signed values.
It also has negative responses to a few Chinese announcement/review terms,
and a small positive response to path-like tokens and early document positions.
The word sets and local English constructions are literal lexical cues,
not a general topic classifier.
"""
READS = ()

DELIMITERS = {
    '<|endoftext|>': 0.924,
    '<think>': 0.083,
    '</think>': 0.186,
    '<tool_call>': 0.030,
    '</tool_call>': -0.062,
    '<tool_response>': 0.079,
    '</tool_response>': -0.050,
    '<|im_start|>': -0.011,
    '<|im_end|>': -0.011,
}
# Chinese announcement/publicity words.
ANNOUNCEMENT = {'宣', '宣传', '宣讲'}
# Review, verification, and judicial examination (both writing systems).
REVIEW = {'审', '審', '审核', '审查', '审判', '审计'}
# Inspection, supervision, and party governance.
OVERSIGHT = {'督导', '督查', '监察', '监督', '纪委', '党委'}
# Poverty alleviation.
POVERTY_RELIEF = {'扶贫', '脱贫', '脱贫攻坚'}
# Media, reporting, Internet, and the 'new era' political slogan.
OFFICIAL_REPORTING = {'媒体', '报道', '互联网', '新时代'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == doc else 0
    carry = (doc, position)
    s = prefix.token_strings[-1]
    if s in DELIMITERS:
        return carry, DELIMITERS[s]
    word = s.strip()
    if word in ANNOUNCEMENT:
        return carry, -0.70
    if word in REVIEW:
        return carry, -0.48
    if word in OVERSIGHT:
        return carry, -0.39
    if word in POVERTY_RELIEF:
        return carry, -0.29
    if word in OFFICIAL_REPORTING:
        return carry, -0.25
    value = -0.0008
    if position:
        value += 0.017 / (1.0 + position / 10.0)
    if s.startswith('/') and (s == '/' or s[1:].isalpha()):
        value += 0.017
    elif word.isalpha() and not s.startswith(' '):
        value += 0.0052
    # Local constructions use only the preceding token in this document.
    previous = prefix.token_strings[-2].strip().lower() if position else ''
    if s == ' to' and previous == 'according':
        value += 0.09
    elif s == ' on' and previous in {'focus', 'focuses', 'focused', 'focusing'}:
        value -= 0.08
    elif s == ' time':
        if previous in {'this', 'each', 'every'}:
            value += 0.075
        elif previous in {'the', 'same', 'first'}:
            value -= 0.04
    return carry, value

