programs.sol:
"""A dry-word feature with weaker responses to nearby spellings.

The strongest negative predictions are for 'dry' and 干/乾/幹, including
uses where those Chinese characters do not mean dry. Inflections and
cry/fry/fly spellings and their Chinese equivalents are weaker. Short
consonant-y fragments have intermediate responses; the preceding chunk
adjusts predictions for 'ry' and related endings. Moisture words and
short capitalized ry spellings have small responses; John is a separate
weak lexical response. Other tokens predict zero. Byte fragments that
complete a Chinese dry character are recognized from the decoded prefix.
"""

READS = ()

DRY = {
    'dry': -6.5, 'drying': -3.9, 'dried': -2.7,
    'dryer': -3.0, 'dryers': -2.8, 'dryness': -2.5,
    'drier': -2.2, 'driest': -2.2, 'dries': -1.7,
    '干': -5.9, '乾': -5.2, '幹': -4.8,
    '干燥': -4.2, '乾燥': -4.2, '烘干': -2.6, '燥': -1.5,
}
RHYMES = {
    'cry': -2.7, 'crying': -1.4, 'cried': -1.3, 'cries': -1.4,
    'fry': -2.9, 'frying': -2.0, 'fried': -1.0, 'fries': -1.6,
    'fly': -1.4, 'flying': -1.2, 'flies': -1.0,
    '哭': -2.5, '飞': -1.8, '飛': -1.3,
}
MOISTURE = {
    'wet': -1.2, 'moist': -1.1, 'damp': -0.3, 'humid': -0.6,
    'rainy': -1.1, 'powder': -0.65, '湿': -1.7, '濕': -1.5,
}
ENDINGS = {'ary': -0.4, 'ery': -0.65, 'ory': -0.27, 'ly': -0.15}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    w = word.lower()
    letter = previous[-1:]
    value = 0.0

    if w in DRY:
        value = DRY[w]
    elif w in RHYMES:
        value = -3.4 if word == 'Cry' else RHYMES[w]
    elif w in MOISTURE:
        value = MOISTURE[w]
    elif w == 'ry':
        if token[:1].isspace():
            value = -1.2
        elif previous.strip('-') == 'd':
            value = -5.8
        elif len(previous) == 1 and previous.isascii() and previous.isalpha():
            value = -3.7
        elif letter in {'c', 'f', 'k', 'w'}:
            value = -3.5
        elif letter == 'r':
            value = -1.7
        elif letter in {'l', 't'}:
            value = -2.2
        elif letter == 'd':
            value = -3.8
        else:
            value = -2.9
    elif w in {'rying', 'ried', 'rier', 'ries'}:
        if letter == 'd':
            value = {'rying': -4.0, 'ried': -2.0,
                     'rier': -2.0, 'ries': -1.6}[w]
        elif w == 'rying':
            value = -1.1 if letter == 'r' else -3.0
        elif w == 'ried':
            value = -1.1 if letter == 'f' else -0.5
        elif w == 'ries':
            value = -0.1 if letter in {'t', 'r'} else -0.7
        else:
            value = -0.55
    elif w in ENDINGS:
        value = ENDINGS[w]
    elif len(w) == 2 and w[1] == 'y' and w[0] in 'cdhwz':
        value = -0.4
    elif len(w) == 3 and w[1:] == 'yn' and w[0] in 'dw':
        value = -1.6 if w[0] == 'd' else -0.85
    elif w in {'bry', 'gry'}:
        value = -2.0 if w == 'bry' else -2.4
    elif w.startswith('ry') and len(w) <= 5:
        value = -2.2 if w == 'rys' else -0.8
    elif word.istitle() and 'ry' in w and len(w) <= 6:
        value = -0.45
    elif w == 'john' or word == '约翰':
        value = -0.65
    elif not token[:1].isspace() and previous == 'dry':
        if w in {'ness', 'er', 'ers'}:
            value = -2.0
    elif '�' in token:
        if prefix.text_prefixes[-1][-1:] in {'干', '乾', '幹'}:
            value = -6.0

    return (doc, w), float(value)

programs.luna:
"""Approximate this sparse component from the current word-piece: strong dry
and cry spellings, plus weaker matching endings and related words.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.lower().strip()

    if word == "dry":
        return None, -5.0
    if word in {"dried", "drying", "dryer", "dryers", "drier"}:
        return None, -2.45
    if "cry" in word:
        return None, -2.15
    if word == "ry":
        return None, -2.05
    if word.endswith("ry"):
        return None, -0.36
    if token.strip() in {"干", "幹"}:
        return None, -3.6
    if "哭" in token:
        return None, -2.0
    if "wet" in word:
        return None, -0.9
    if "fly" in word or "flew" in word or "飞" in token:
        return None, -1.15
    return None, 0.0

programs.sol:
"""Document-opening cues and commas in short programming-style argument lists.

Approximate two conspicuous effects: document openings and code-list commas.
Opening strength uses familiar introductory words, source directives, heading
markers, case and whitespace; initial chat headers have a negative response. Commas
get a positive response in short unfinished argument, literal and type lists,
or import statements. This symbolic parser is approximate; ordinary lexical
variation away from these cases is left at zero.
"""
import math
import re

READS = ()

QUESTION_WORDS = {'How', 'Why'}
INTRODUCTIONS = {'The', 'This', 'In', 'We', 'You', 'It', 'There'}
SOURCE_STARTS = {'import', 'package'}
DECLARATIONS = {'def', 'class', 'const', 'var', 'function', 'export'}
TYPE_CHECKS = {'isinstance', 'issubclass', 'hasattr'}
MATH_FUNCTIONS = {'gcd', 'lcm', 'log'}


def opening(s):
    if s == '<|im_start|>':
        return -0.505
    if s in SOURCE_STARTS:
        return 1.22
    if s in {'from', '#include'}:
        return 0.97
    if s in DECLARATIONS:
        return 0.72
    if s == 'What':
        return 1.36
    if s in QUESTION_WORDS:
        return 0.97
    if s in {'Where', 'Who', 'When', 'Which'}:
        return 0.53
    if s in INTRODUCTIONS:
        return 0.75
    if s.startswith(('#', '//', '/*', '<?')):
        return 0.56
    if s == 'Title':
        return 1.66
