    stack, prev_tok = carry if carry is not None else ([], "")
    doc = prefix.document_ids
    tok = prefix.token_strings[-1]
    first = len(doc) == 1 or doc[-1] != doc[-2]
    if first:
        stack = []
    stack = [n + 1 for n in stack]
    value = 0.0
    if prev_tok == "<|endoftext|>":
        value = -0.5 if tok == "<|im_start|>" else 0.33
    elif first:
        value = 0.13
    elif tok == "<|im_start|>":
        value = -0.06
    elif prev_tok == "<|im_start|>" and tok == "user":
        value = -0.12
    elif tok == "," and stack:
        value = 0.5 / (1 + stack[-1] / 3)
    for ch in tok:
        if ch in OPEN:
            stack.append(0)
        elif ch in CLOSE and stack:
            stack.pop()
