    return None, 0.0

programs.sol:
"""A sparse lexical model of fiction/fantasy vocabulary and text boundaries.

Fiction, fantasy adventures, and Chinese fantasy-game terms receive negative
responses; factual-media vocabulary receives a small positive one.  A fiction
cue strengthens related words for the next three tokens.  Recognize compound
endings and split spellings, but do not infer a document's topic.  Explicit
thought/tool delimiters and user-role headers have their own responses.
Unrecognized tokens stay near zero: their idiosyncratic responses are omitted.
"""
import re

READS = ()
FICTION = {'fiction', 'fictional', 'novels', 'fantasies'}
FANTASY = {'fantasy', 'tolkien'}
ADVENTURES = set('adventure adventures adventurers epic tale tales chronicles '
                 'mythical mythology medieval'.split())
FANTASY_GAMES = set('rpg mmorpg mmo dungeon dungeons tabletop elves wizard '
                    'wizards gamers multiplayer'.split())
LITERATURE = set('novel book books comic comics storyline storytelling plot'.split())
GAMES = set('game games gaming gameplay player players character characters'.split())
WORLDS = {'story', 'stories', 'world', 'worlds'}
FACTUAL_MEDIA = set('documentary documentaries journalist journalists journalism '
                    'interview interviews magazine magazines'.split())
NEWS_HISTORY = {'news', 'history', 'historical', 'science'}
CHINESE_FICTION = {'小说', '小說', '奇幻', '科幻', '武侠', '武俠', '幻想'}
CHINESE_GAMES = {'游戏', '遊戲', '游戏中', '玩家', '玩家们', '扮演', '冒险', '探险',
                 '手游', '网游', '梦境'}
GAME_SERVER_TERMS = {'私服', '新开', '合击', '单职业'}
CUES = FICTION | FANTASY | ADVENTURES | FANTASY_GAMES
RELATED = LITERATURE | GAMES | WORLDS
GROUPS = (
    (FICTION, -0.49), (FANTASY, -0.63), (ADVENTURES, -0.33),
    (FANTASY_GAMES, -0.24), (LITERATURE, -0.074), (GAMES, -0.053),
    (WORLDS, -0.023), (FACTUAL_MEDIA, 0.15), (NEWS_HISTORY, 0.057),
)
SPELLINGS = CUES | RELATED | FACTUAL_MEDIA | NEWS_HISTORY


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail, recent, position = '', '', 0, 0
    if carry is not None and carry[0] == doc:
        _, previous, tail, recent, position = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    # For example, T + olkien and D + ungeons finish recognizable words.
    if token and token[0].isalpha() and tail + word in SPELLINGS:
        word = tail + word
    value = 0.0003
    for words, strength in GROUPS:
        if word in words:
            value += strength
            break
    legend = '传奇' in token
    cue = word in CUES or token in CHINESE_FICTION or legend
    if token in CHINESE_FICTION:
        value = -0.60 if token in {'小说', '小說'} else -0.38
    if token in CHINESE_GAMES:
        value = -0.18
    if legend or token in GAME_SERVER_TERMS:
        value = -0.51 if legend else -0.33
    if token in {'传奇私服', '迷失传奇', '热血传奇'}:
        value = -0.70
    if token in {'新开传奇', '单职业', '奇幻'}:
        value = -0.95
    prev = previous.strip().lower()
    if ((prev == 'comic' and word in {'book', 'books', '-book'})
        or (prev in {'sci', 'science'} and word in {'-fi', 'fiction', '-fiction'})
        or (prev == 'role' and word in {'play', 'playing', '-playing'})
        or (prev == 'fairy' and word in {'tale', 'tales'})):
        value = -0.50
    elif token == '-fiction':
        value = -0.28
    if recent:
        if word in RELATED or token in CHINESE_GAMES | {'世界', '网站', '发布'}:
            value -= 0.36
        elif cue:
            value -= 0.13
    if token == '</think>':
        value = -0.724
    elif token == '</tool_response>':
        value = 0.10
    elif token == '</tool_call>':
        value = 0.06
    elif token == '<|endoftext|>':
        value = 0.030
    elif token == 'user':
        if position == 0:
            value = 0.133
        elif previous == '<|im_start|>':
            value = 0.209 if position == 1 else (0.08 if position < 40 else 0.054)
    # Bounded spelling memory; all state resets at a new document.
    ending = re.search(r'[A-Za-z]+$', token)
    if ending:
        tail = ((tail if token.isascii() and token.isalpha() else '')
                + ending[0].lower())[-20:]
    else:
        tail = ''
    recent = 3 if cue else max(0, recent - 1)
    return (doc, token, tail, recent, position + 1), float(value)

