"""Layer-0 MLP down-projection, component 5003.

What it does: it writes a negative push into the residual stream on two kinds of token.
1. The closing think tag "</think>" that chat templates put after an empty reasoning block
   ("<think>\\n\\n</think>"). This is the strongest and most reliable response (about -0.72).
2. Words of fantasy and fiction genre ("fantasy", "fiction", "novels", "chronicles", "tale",
   "adventure", "medieval", "epic", "wizard"), with a weaker response to the wider
   genre and game vocabulary ("novel", "quest", "dragon", "genre", "gaming").
Everything else is predicted as 0; the component's small diffuse activity is not modelled.
"""

READS = ()

STRONG = {"fantasy": -0.6, "fiction": -0.5, "fictional": -0.5, "novels": -0.5, "chronicles": -0.4}
MEDIUM = {
    "tale": -0.35, "tales": -0.3, "adventure": -0.35, "adventures": -0.35, "medieval": -0.3,
    "epic": -0.3, "wizard": -0.25, "heroes": -0.2, "saga": -0.15,
}
WEAK = {"novel": -0.2, "quest": -0.12, "dragon": -0.15, "genre": -0.15, "gaming": -0.15,
        "worlds": -0.2, "battles": -0.17, "horror": -0.13, "anime": -0.11, "myth": -0.14}
LEXICON = {**WEAK, **MEDIUM, **STRONG}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "</think>":
        return carry, -0.72
    return carry, LEXICON.get(token.strip().lower(), 0.0)

