    'public': (-0.04, 1.72), 'private': (-0.04, 1.72),
    'internal': (-0.04, 1.72), 'protected': (-0.03, 0.7),
    'static': (-0.03, 0.7), 'override': (-0.03, 0.7),
    'readonly': (0.5, 2.15), 'string': (-0.08, 1.1),
    'bool': (-0.06, 1.78), 'int': (-0.03, 0.61),
    'float': (0.0, 0.6), 'double': (0.0, 0.6),
    'decimal': (0.18, 1.1), 'void': (0.3, 1.1),
    'var': (-0.06, 1.75), 'new': (-0.03, 1.14),
    'null': (0.1, 0.8), 'foreach': (0.07, 2.0),
    'typeof': (0.06, 1.53), 'namespace': (0.0, 3.03),
    'async': (0.0, 1.32), 'await': (0.0, 1.32),
    'object': (-0.18, 1.06), 'Task': (0.4, 1.63),
}
INTERFACES = set('''
IEnumerable ICollection IEnumerator IQueryable IDisposable IEquatable
'''.split())
HIGH_APIS = set('''
WriteLine ReadLine IsDBNull IsNullOrEmpty AreEqual TryParse ContainsKey
'''.split())
NAMESPACES = set('''
Collections Linq Tasks Threading Runtime Forms Net Framework Xna Drawing
'''.split())
CONVERSIONS = set('''
