UNITY = set('''
UnityEngine MonoBehaviour GameObject Mathf KeyCode Quaternion GetComponent
FindObjectOfType
'''.split())
EXCEPTION = re.compile(
    r'^(Argument\w*|InvalidOperation|NotImplemented|NullReference|ObjectDisposed)Exception$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        score, recent, position, other, line_start = 0.0, '', 0, False, True
    else:
