           or word in {'DateTimeOffset', 'SerializeField', 'IntPtr', 'DllImport'}
           or EXCEPTION.fullmatch(word)
           or word.endswith(('EventArgs', 'DbContext', 'SqlConnection'))
           or core in {'.WriteLine', '.ReadLine', '.IsDBNull', '#region', '#endregion'}
           or any(tag in text for tag in ('<summary', '<param ', '<returns', ' cref='))
           or '```csharp' in text or 'C#' in text or '{ get; set;' in text)
