        score, other = 1.0, False
    if not other and (word == 'foreach' and '$' not in recent
                      or core in {'(string', '<string', '(bool', '<bool'}):
        score = 1.0
    if not other and word == 'using' and line_start:
        score = 1.0
    if re.search(r'\b(public|private|static|readonly|override)\s+(string|bool)\b', text):
        score, other = 1.0, False
