    elif word in INTERFACES:
        value = 4.8
    elif EXCEPTION.fullmatch(word):
        value = 4.6 if token.startswith(' ') else 5.9
    elif word.endswith('EventArgs'):
        value = 3.9
    elif word == 'DateTimeOffset':
        value = 5.55 if token.startswith(' ') else 4.75
    elif word == 'SerializeField':
        value = 5.37
    elif word in {'DateTime', 'TimeSpan'}:
        value = 0.32 + 1.97 * score + (0.92 if token.startswith(' ') else 0.0)
    elif word == 'Console':
        value = 0.8 + 1.77 * score + (0.32 if token.startswith(' ') else 0.0)
    elif word == 'System':
