def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    # Bars often mark table columns, math notation, or pipelines; && is a
    # common code and shell conjunction.
    if "|" in token or "&&" in token:
        return None, CALIBRATION * 0.64

    # Recognize familiar .NET-style member names; other capitalized members
    # receive a smaller guess.
    if token.startswith(".") and len(token) > 1 and token[1].isupper():
        if token == ".WriteLine":
            value = 3.7
        elif token == ".ToString":
            value = 3.2
        elif token == ".Drawing":
            value = 1.2
        else:
            value = 0.45
        return None, CALIBRATION * value

    if token == " Azure":
        return None, CALIBRATION * 1.3

    return None, 0.0

