"""Pronouns continuing a relative/embedded clause, approximated by local word classes.

Space-prefixed subject pronouns get a strong negative response after 'what',
relative markers and noun-like words. Punctuation, function words and common
verbs largely suppress it. 'It', 'that' and capitalized forms are weaker.
These are lexical heuristics, not a parser. All other tokens are zero except
Romance 'que'. The short text history resets at document boundaries.
"""
import re

READS = ()
FUNCTION_WORDS = set('''if when while because since although though unless until
 after and but nor or so then now maybe perhaps however therefore thus hence
 eventually certainly probably really also just even still yet instead plus
 such yes no lest till unto to of for with from by in on at into onto upon over under about
 between through within among without despite like against toward towards
 is are was were be been being am do does did have has had can could will would
 shall should may might must'''.split())
VERBS = set('''think know believe hope wish suppose assume suggest expect
 understand remember forget imagine guess doubt feel realize consider mean see
 hear notice say tell ask show note mention indicate report explain announce
 reveal prove demonstrate confirm verify ensure argue claim insist agree admit
 conclude observe recall imply discover learn give allow provide inform thank
 offer teach remind promise enable encourage invite recommend introduce assure convince advise make
 get take put keep use find add try want need let help bring send choose watch
 stop start read write look listen accept create build become seem appear
 follow save remove fix solve update prevent replace share avoid decide
 compute calculate implement describe modify convert compare'''.split())
PREDICATE_ADJECTIVES = set('sure certain glad happy sorry afraid aware clear '
                           'possible likely obvious confident evident'.split())
MODIFIERS = set('''able important good bad new old right wrong first last next
 previous same different less today yesterday tomorrow later earlier ago only
 not never already sometimes often always usually finally least here there
 otherwise above below inside outside around near far long again well out up
 down away together'''.split())
ENTITY_WORDS = set('''thing things something anything everything nothing data
 information evidence resource resources file files item items'''.split())
IRREGULAR = dict(said='say', told='tell', knew='know', thought='think',
                 gave='give', given='give', made='make', got='get', seen='see',
                 saw='see', found='find', took='take', taken='take',
                 heard='hear', felt='feel')


def forms(word):
    result = {word, IRREGULAR.get(word, word)}
    if word.endswith('s'):
        result.add(word[:-1])
    if word.endswith('es'):
        result.add(word[:-2])
    if word.endswith('ed'):
        result.update((word[:-1], word[:-2]))
    if word.endswith('ing'):
        result.update((word[:-3], word[:-3] + 'e'))
    return result


def response(history, previous_token):
    # Triples are responses for subject pronouns, 'it', and 'that'.
    match = re.search(r'([A-Za-z]+)[ \t]*$', history)
    if not match:
        return (-0.07, -0.04, -0.18)
    original = match.group(1)
    word = original.lower()
    if word in {'what', 'whatever'}:
        return (-4.42, -3.73, -1.83)
    if word in {'which', 'who', 'whom'}:
        return (-3.57, -2.89, -0.93)
    if word == 'that':
        return (-1.58, -0.97, -0.32)
    if word in {'where', 'how', 'why', 'wherever'}:
        return (-1.46, -0.95, -0.42)
    if word in {'as', 'before', 'once', 'whether', 'than', 'whenever'}:
        return (-0.54, -0.26, -0.10)
    if word in ENTITY_WORDS:
        return (-4.83, -3.11, -1.21)
    if word in {'all', 'one', 'ones', 'someone', 'everyone', 'anyone',
                'more', 'much', 'best'}:
        return (-3.45, -1.99, -1.01)
    # Common nouns whose spellings also resemble verbs or adjective endings.
    if word in {'work', 'works', 'change', 'changes', 'state', 'states', 'notes',
                'table', 'cable', 'variable', 'interval', 'signal', 'animal',
                'trial', 'proposal', 'material', 'derivative', 'packaging'}:
        return (-3.10, -1.45, -0.80)
    if word in FUNCTION_WORDS or word in PREDICATE_ADJECTIVES or forms(word) & VERBS:
        return (-0.05, 0.04, 0.05)
    if word in MODIFIERS or word.endswith('ly'):
        return (-0.95, -0.40, -0.15)
    if (len(word) <= 2 or original[0].isupper()
            or (previous_token.isalpha() and previous_token != original)):
        return (-1.32, -0.62, -0.47)
    if word.endswith(('ing', 'ed', 'ful', 'ous', 'ive', 'al', 'able', 'ible')):
        return (-0.95, -0.40, -0.15)
    if word.endswith('s') and not word.endswith('ss'):
        return (-3.77, -1.45, -1.03)
    return (-2.78, -0.95, -0.74)


CAPITAL_GAIN = {'They': 0.61, 'She': 0.51, 'He': 0.42,
                'We': 0.26, 'You': 0.67, 'It': 0.22}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token[1:] if token.startswith(' ') else ''
    value = 0.0
    if (word in {'I', 'we', 'you', 'he', 'she', 'they', 'it', 'that'}
            or word in CAPITAL_GAIN):
        previous = ''
        if history and len(prefix.token_strings) > 1:
            previous = prefix.token_strings[-2]
        values = response(history, previous)
        if word in CAPITAL_GAIN:
            gain = CAPITAL_GAIN[word]
            value = values[0] * gain + 0.2 * gain
        else:
            value = values[1 if word == 'it' else 2 if word == 'that' else 0]
            if word == 'I':
                value = value * 0.95 + 0.05
            elif word in {'he', 'she'}:
                value = value * 0.94 - 0.19
    elif token == ' que':
        value = -0.60
    return (doc, (history + token)[-80:]), float(value)

