SUBJECT_PRONOUNS = {
    "we": -1.15,
    "you": -1.75,
    "he": -1.5,
    "she": -1.75,
    "they": -1.5,
    "that": -0.55,
    "it": -0.28,
    "this": -0.23,
}

FUNCTION_WORDS = set("""
    a an the this that these those
    of to in on at by for from with about as into over under through
    and or but if while because although
    is am are was were be been being
    have has had do does did can could will would shall should may might must
    i we you he she it they me us him her them my our your his its their
    who which what where when why how
    said says say asked told replied
""".split())

RELATIVE_MARKERS = {"which", "who", "whom", "whose"}
TITLE_LABELS = {"book", "part", "chapter", "volume", "section", "act", "scene"}


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1].strip()
    if len(prefix.token_strings) < 2:
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0

    previous = prefix.token_strings[-2].strip().casefold()
    if not previous or not any(char.isalpha() for char in previous):
        return None, 0.0

    if current == "I":
        if previous in TITLE_LABELS:
            return None, 0.0
        if previous in FUNCTION_WORDS and previous not in RELATIVE_MARKERS:
            return None, 0.0
        return None, -1.25

    word = current.casefold()
    if previous in FUNCTION_WORDS and previous not in RELATIVE_MARKERS:
        return None, 0.0
    return None, float(SUBJECT_PRONOUNS.get(word, 0.0))

programs.sol:
"""A mostly lexical lesson/course detector, strongest on Chinese lesson words.

'Of course' also fires; 'golf course' is suppressed. Selected teaching terms,
meal words, goods, arts and games give smaller responses. Other tokens
get only a small negative document-start response that quickly fades.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    token = prefix.token_strings[-1]
    word = token.strip()
    # Include punctuation-delimited words in names such as '_course'.
    lower = word.strip('_.-/()').lower()
    previous = ''
    if (len(prefix.token_strings) > 1
            and prefix.document_ids[-2] == doc):
        previous = prefix.token_strings[-2].strip()

    value = 0.0
    if lower == 'course':
        value = 1.25
        if word == 'course':
            value = 1.0
        elif word == 'Course':
            value = 1.4
        if previous == 'of':
            value = 1.4
        if previous.lower() == 'golf':
            value = 0.2
    elif lower == 'courses':
        value = 0.2 if previous.lower() == 'golf' else 1.07
    elif lower in {'lesson', 'lessons'}:
        value = 1.35 if lower == 'lesson' else 1.12
        if token == 'Lesson':
            value = 1.65
    elif lower == 'homework':
        value = 0.65 if word[0].isupper() else 0.84
    elif lower in {'lecture', 'lectures', 'curriculum', 'coursework'}:
        value = 0.5
    elif lower in {'teacher', 'teachers', 'classroom', 'undergraduate',
                   'teaching', 'instructor'}:
        value = 0.2
    elif word in {'课', '課'}:                 # lesson characters
        value = 5.9 if word == '课' else 5.3
        if previous == '下':                   # finishing class
            value -= 1.0
    elif word in {'课程', '課程', '上课', '授课', '节课', '讲课'}:
        value = 2.7                            # courses / class sessions
    elif word in {'课堂', '课堂教学'}:
        value = 2.1                            # classroom / classroom teaching
    elif word in {'课题', '功课', '课文', '课本', '课外'}:
        value = 1.5                            # assignments / lesson materials
    elif word in {'科', '科目', '学科', '教材', '老师', '老師',
                  '讲师', '講師', '讲座'}:
        value = 0.65                           # subjects, books, teachers
    elif word in {'考试', '考試', '教学', '教學', '本科', '学期', '班'}:
        value = 0.5                            # exams and school organization
    elif word in {'教程', '科研', '本科生', '高考', '毕业', '畢業'}:
        value = 0.35
    elif lower in {'курс', 'cours', 'cursos', 'учеб'}:
        value = 0.5                            # course / study word stems
    elif word in {'饭', '飯', '茶', '膳'}:
        value = 0.8                            # rice, meals, tea
    elif word in {'酒', '吃饭', '晚饭', '粥'}:
        value = 0.55                           # wine, dining, porridge
    elif word in {'菜', '炒', '做饭', '茶叶'}:
        value = 0.35                           # dishes, cooking, tea leaves
    elif lower in {'dish', 'dishes', 'wine', 'tea'}:
        value = 0.23
    elif word in {'货', '貨', '购物', '購物', '供货', '发货', '送货'}:
        value = 0.65                           # goods, shopping, deliveries
    elif word in {'舞', '戏', '棋', '剧', '舞台', '台词'}:
        value = 0.4                            # dance, plays, games
    elif word == '歌':
        value = 0.2                            # song

    value -= 0.05 / (position + 1) ** 1.7
    return (doc, position), value

programs.haiku:
"""Education words: the component fires on the token for a course, lesson or class.

Layer-0 MLP neuron-like component (down_proj:5007). Its activation depends almost only on the
current token, not on the context around it. So the program is a lookup by word meaning:

- 课 / 課 (Chinese "class, lesson") alone: strongest, about 5.7.
- other Chinese words containing 课 (课程 "course", 课堂 "classroom", 讲课 "teach a class"): about 2.4.
- English "course" / "lesson" (any case, singular or plural): about 1.3.
- "homework", "curriculum", "lecture": about 0.6.
- other Chinese education nouns (教学 teaching, 老师 teacher, 讲师 lecturer, 考试 exam,
  作业 homework, 科目 subject, 班级 class, ...): about 0.4.
- every other token: 0.

The values are the mean activation for each group in a sample of training text.
"""

from collections.abc import Mapping

READS = ()

CLASS_CHAR = {"课", "課"}
COURSE_EN = {"course", "courses", "lesson", "lessons"}
EDU_EN = {"homework", "curriculum", "lecture", "lectures"}
EDU_ZH = {
    "教学", "老师", "老師", "教师", "讲师", "讲座", "考试", "科目", "学科", "作业",
    "教程", "教材", "班", "班级", "科", "学校", "学生",
}


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if token in CLASS_CHAR:
        value = 5.7
    elif "课" in token or "課" in token:
        value = 2.4
    elif word in COURSE_EN:
        value = 1.3
    elif word in EDU_EN:
        value = 0.6
    elif token.strip() in EDU_ZH:
        value = 0.4
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate a sparse positive signal for course and classroom vocabulary.

Course and lesson words get the largest English estimates, with smaller values
for homework and related school terms. Most tokens receive zero.
"""

READS = ()

COURSES = {"course", "courses", "cours", "курс"}
LESSONS = {"lesson", "lessons"}
CLASSROOM_WORDS = {
    "lecture", "lectures", "teacher", "classroom", "textbook",
    "instructor", "curriculum", "seminar", "undergraduate",
}
CHINESE_COURSES = {"课", "课程", "课题", "课堂"}
CHINESE_SCHOOL_WORDS = {
    "科", "科目", "考试", "讲师", "老师", "科研", "教程", "研究生",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in COURSES:
        return None, 1.25
    if word in LESSONS:
        return None, 1.35
    if word == "homework":
        return None, 0.5
    if word in CHINESE_COURSES:
        return None, 1.8 if word != "课" else 4.0
    if word in CLASSROOM_WORDS or word == "학교":
        return None, 0.25
    if word in CHINESE_SCHOOL_WORDS:
        if word in {"科研", "教程", "研究生"}:
            return None, 0.35
        return None, 0.65
    return None, 0.0

programs.sol:
"""A spelling-based approximation of a heterogeneous first-layer signal.

Conversation boundaries and closing reasoning/tool markers are strong
positives. Other text uses script, length, case, function words and familiar
English suffixes. Bare suffix fragments and technical endings get separate
contributions. Constants balance activation fit and causally important
training positions. This is token-local; detailed word-specific responses are
intentionally not represented by a vocabulary lookup table.
"""
READS = ()

BOUNDARIES = {
    '<|im_end|>': 1.13, '<|im_start|>': 0.87,
    '</think>': 0.93, '<think>': 0.02,
    '<tool_call>': 0.50, '</tool_call>': 0.86,
}
FUNCTION_WORDS = set('''
a an the this that these those i you he she it we they me him her us them
my your his its our their is am are was were be been being have has had
will would shall should can could may might must do does did not no
and or but nor so yet if as than because although though whether
to of for from in on at by with without into onto over under upon about
during before after since until when where who whom whose which what how
all any each every some such other another both either neither
'''.split())
# Suffix groups contribute additively.
ENDINGS = (
    (('ness', 'hood', 'ship'), 0.41),
    (('tion', 'ment', 'ity', 'ism'), -0.099),
    (('al', 'ic', 'ful'), 0.104),
    (('less',), 0.271),
    (('ive', 'ary', 'able'), -0.065),
    (('ed',), -0.153),
    (('ing',), -0.143),
    (('ly',), -0.034),
    (('s',), -0.115),
    (('er',), -0.068),
)
SCRIPTS = (
    (0x3400, 0xA000, -0.067, 0.098), # Chinese
    (0x3040, 0x30A0, -0.05, 0.231), # Hiragana
    (0x30A0, 0x3100, -0.115, 0.049), # Katakana
    (0xAC00, 0xD7B0, -0.0, 0.114), # Korean
    (0x0400, 0x0530, -0.158, -0.004), # Cyrillic
    (0x0600, 0x0700, -0.118, 0.079), # Arabic
    (0x0370, 0x0400, -0.139, -0.08), # Greek
    (0x0E00, 0x0E80, -0.004, 0.222), # Thai
)


def spelling_value(token):
    if token in BOUNDARIES:
        return BOUNDARIES[token]
    word = token.strip()
    if not word:
        return 0.012
    low = word.lower()
    if word.isdigit():
        return -0.002
    if word[0] in '、。':
        return -0.062
    if word.isascii() and word.isalpha():
        value = 0.121
        if token[0].isspace():
            value -= 0.01
        if len(word) < 3:
            value -= 0.048
        if low in FUNCTION_WORDS:
            value -= 0.059
        if word[0].isupper():
            value += 0.024
        if word.isupper() and len(word) > 1:
            value += 0.101
        elif any(ch.isupper() for ch in word[1:]):
            value += 0.364
        if low[-1] in 'aeiouy':
            value -= 0.071
        for endings, weight in ENDINGS:
            if any(len(low) > len(e) + 2 and low.endswith(e)
                   for e in endings):
                value += weight
        # Bare abstract-noun/adjective suffixes and the chemical suffix -yl.
        if low in ('ness', 'ful', 'sion', 'yl'):
            value += 0.712
        if low.endswith('ph'):
            value += 0.479
        elif low.endswith(('th', 'gh', 'ck', 'sh')):
            value += 0.092
        return value
    if word.isascii() and not any(ch.isalnum() for ch in word):
        repeated = len(word) > 1 and len(set(word)) == 1
        return 0.008 + (0.073 if repeated else 0.0)
    value = 0.134
    for lo, hi, short, long in SCRIPTS:
        if any(lo <= ord(ch) < hi for ch in word):
            value += long if len(word) > 1 else short
    if '\ufffd' in word:
        value -= 0.082
    return value


def step(carry, prefix, upstream):
    return None, float(spelling_value(prefix.token_strings[-1]))

programs.haiku:
"""Layer-0 MLP down_proj component 5008: a token-level detector with a weak, mostly
lexical profile.

Its activation depends almost only on the current token (not on the preceding context,
and hardly on the document). It is near zero for ordinary text, and is clearly positive on
a few groups of tokens:
  * chat / tool markup control tokens (<|im_start|>, <|im_end|>, </think>, </tool_call>,
    and the opening <think>, <tool_call>), the strongest and most common firing;
  * runs of middle-dot leaders (·· as in a table of contents), a constant ~0.65;
  * CJK ideographs, a mild positive (~0.1).
Everything else gets a small baseline: words ~0.04, punctuation, spaces and digits ~0.

This program writes those token classes down and nothing else. It does not model the many
individual content words that fire (for example " static", " great", " minimum"), so it
explains only a small share of the variance.
"""

READS = ()

# Mean activation on each control token, as measured on training text.
CONTROL_TOKENS = {
    "<|im_start|>": 0.9,
    "<|im_end|>": 1.1,
    "</think>": 0.9,
    "</tool_call>": 0.9,
    "<tool_call>": 0.5,
    "<think>": 0.4,
}
LEADER_CHARS = set("·…")


def is_cjk(s):
    return any(0x3000 <= ord(c) <= 0x9FFF or 0xAC00 <= ord(c) <= 0xD7AF for c in s)


def predict_token(s):
    """The component's activation for the token string `s` (decoded alone)."""
    if s in CONTROL_TOKENS:
        return CONTROL_TOKENS[s]
    if len(s) >= 2 and set(s) <= LEADER_CHARS:
        return 0.65
    body = s.strip()
    if not body:
        return 0.0
    if is_cjk(body):
        return 0.1
    if body.isdigit() or all(not c.isalnum() for c in body):
        return 0.0
    return 0.04


def step(carry, prefix, upstream):
    # Stateless: the activation depends only on the current token.
    return None, float(predict_token(prefix.token_strings[-1]))

programs.sol:
"""A lexical approximation of a reader/viewer and recommendation response.

Recognize books, films, reviews, recommendations and consuming content,
including common non-English expressions. Reading gets a larger response
in personal or book-related contexts, and a smaller one in technical
contexts. Recognize a few continuations such as 'listening to' and title
brackets. Everything else is zero; context resets between documents.
"""
READS = ()

# Vocabulary grouped by familiar meanings, with approximate amplitudes.
FAMILIES = (
    (0.95, {'book', 'books', 'paperback', 'kindle'}),
    (0.70, {'ebook', 'ebooks', 'isbn', 'bookstore', 'reader', 'readers'}),
    (0.92, {'movie', 'movies'}),
    (0.52, {'film', 'films', 'cinema', 'netflix', 'dvd', 'dvds'}),
    (0.55, {'novel', 'novels', 'fiction', 'manga', 'anime'}),
    (0.73, {'review', 'reviews', 'reviewed', 'reviewing'}),
    (0.55, {'recommend', 'recommends', 'recommended', 'recommending',
            'recommendation', 'recommendations'}),
    (0.80, {'favorite', 'favourite', 'favorites', 'favourites'}),
    (0.80, {'watch', 'watches', 'watching', 'watched'}),
    (0.60, {'listen', 'listening', 'listened'}),
    (0.30, {'library', 'literature', 'literary', 'classic', 'shelf',
            'shelves', 'textbook', 'textbooks', 'finish', 'finishing'}),
    (1.12, {'电影', '電影', '看电影', '观看'}),
    (1.40, {'放映', '看了', '看过', '看完', '观影', '读书'}),
    (0.90, {'书', '书中', '书籍', '读', '讀', '阅读', '閱讀',
            '推荐', '推薦', 'おすすめ', 'オススメ', '本書'}),
    (0.65, {'看', '我看', '看到', '看着', '看著', '影片', '小说',
            '書', '読', '読んで', '読み', 'レビュー', '영화'}),
    (0.30, {'本', '片', '影', '部'}),
    (0.55, {'libro', 'livro', 'buch', 'bücher', 'película', 'lesen'}),
)
WORDS = {word: weight for weight, words in FAMILIES for word in words}
MEDIA = {'book', 'books', 'film', 'films', 'movie', 'movies',
         'novel', 'novels', 'fiction', 'story', 'stories', 'kindle'}
TECHNICAL = {'file', 'files', 'data', 'input', 'stream', 'buffer',
             'register', 'registers', 'sensor', 'pressure', 'voltage',
             'memory', 'error', 'properties', 'measurement'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    previous = recent[-1] if recent else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('._/-(')
    value = WORDS.get(word, 0.0)
    if word in {'book', 'books', 'movie', 'movies', 'review', 'reviews'}:
        value *= 1.0 if token[:1].isspace() else 0.72
    if word == 'books':
        value += 0.20
    if word in {'read', 'reading'}:
        value = 0.43 if word == 'read' else 0.83
        if not token[:1].isspace():
            value = 0.30 if word == 'read' else 0.50
        if previous in {'i', 'have', 'had', "'ve", '’ve', 'ever'}:
            value = 1.65
        elif previous in {'you', 'we', 'he', 'she', 'they', 'to'}:
            value = 0.77
        if word == 'read' and previous in {
                'is', 'are', 'be', 'the', 'cannot', '='}:
            value = 0.08
        if word == 'reading' and previous in {
                'been', 'was', 'were', "'m", 'enjoy', 'enjoyed', 'stop'}:
            value = 1.65
        if any(w in MEDIA for w in recent):
            value += 1.0
        if any(w in TECHNICAL for w in recent):
            value = 0.10 if word == 'read' else 0.24
    elif word == 'recommend':
        value = 1.53 if previous == 'i' else 0.85
        if previous == 'highly':
            value = 1.85
    elif word == 'of' and previous in {'book', 'review', 'reading'}:
        value = 0.30
    elif word == 'to' and previous in {'listen', 'listening', 'listened'}:
        value = 0.38
    elif word in {'the', 'this', 'it', 'a'} and previous in {'read', 'reading'}:
        value = 0.23
    elif word in {'series', 'show', 'shows'}:
        if previous in MEDIA | {'tv', 'television'}:
            value = 0.65
    if word.startswith(('филь', 'кино')):
        value = 0.65
    elif word.startswith('кни'):
        value = 0.85
    elif '《' in token:
        value = 0.95
    elif token == '/watch':
        value = 1.70 if 'youtube' in recent else 1.10
    return (doc, (recent + (word,))[-12:]), float(value)

"""Short alphabetic chunks ending in Latin s/S give a negative response.

The main signal is s/S alone, consonant-only two-letter chunks, and capital
abbreviations ending in S. Vowels and continuation of an ordinary longer
word reduce it; apostrophe-s inside one token is quiet. Document-initial
letters have their own calibration. State resets at document boundaries.
The constants
calibrate a few alphabetic cluster families, not a vocabulary lookup.
"""
import re
import unicodedata

READS = ()
WORD_END = re.compile(r'([^\W\d_]+)$')
VOWELS = frozenset('aeiou')
CAPITAL_PAIRS = {'B': 3.1, 'C': 3.15, 'D': 3.5, 'G': 3.9,
                 'K': 3.2, 'P': 2.65, 'W': 2.3, 'Q': 2.2}


def latin_vowels(text):
    plain = unicodedata.normalize('NFKD', text)
    return sum(c.lower() in VOWELS for c in plain)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    word, previous = ('', '') if fresh else carry[1:]
    token = prefix.token_strings[-1]
    match = WORD_END.search(token)
    part = match[1] if match else ''
    separated = bool(match and match.start())
    word = word + part if part and not separated else part
    carry = (doc, word[-64:], token)
    if not part or not token.endswith(('s', 'S')):
        return carry, 0.0
    if separated and token[-2:-1] in "'’":
        return carry, 0.0
    if fresh and token in ('s', 'S'):
        return carry, -2.04 if token == 'S' else -1.34

    length = len(part)
    upper = part.isupper()
    before = part[-2:-1]
    vowels = latin_vowels(part)
    word_vowels = latin_vowels(word)
    previous_vowels = 0 if separated else latin_vowels(previous)
    tail = len(word) - max((i + 1 for i, c in enumerate(word)
                           if latin_vowels(c)), default=0)
    short_word = len(word) <= 4

    if vowels:
        if upper and short_word and length <= 3:
            strength = 1.0 if tail >= 2 else 0.38
        else:
            strength = 0.0
    elif length == 2 and upper:
        strength = CAPITAL_PAIRS.get(before, 1.54)
        if before == 'B' and word_vowels:
            strength = 1.77
    elif length == 2 and before.islower():
        if before in 'bcdg':
            strength = 3.0 if before == 'g' else 2.6
            if previous_vowels:
                strength *= 0.5 if before != 'g' else 0.65
        elif before in 'pwx':
            strength = 2.2 * (0.5 if previous_vowels else 1.0)
        elif before in 'fjqvry':
            strength = 1.5 * (0.65 if previous_vowels else 1.0)
        elif before in 'klt':
            strength = 1.4 * (0.4 if previous_vowels else 1.0)
        else:
            strength = 0.9 * (0.6 if previous_vowels else 1.0)
        if separated and token[:1] == '.':
            strength *= 0.8
    elif length == 2:
        strength = 0.8
    elif length > 2:
        if upper:
            strength = 2.43 if before == 'B' else 1.02
        else:
            strength = 0.39 if short_word else 0.07
    elif upper:
        strength = 1.33
        if not separated and not word_vowels and previous[-1:].isalpha():
            strength = 2.2 if len(previous) >= 2 else 1.6
        elif not short_word:
            strength = 0.62 if sum(c.isupper() for c in previous) >= 3 else 1.63
        if separated and token[:1] in '.(-':
            strength = 1.1
    elif short_word:
        strength = (0.35 if tail == 1 else 0.94) if word_vowels else 1.1
        if separated and token[:1] in './':
            strength = 1.4
    else:
        strength = 0.14 if tail == 1 else 0.7 if len(previous) <= 4 else 0.46
    return carry, -strength

programs.haiku:
"""Component layers.0.mlp.down_proj:5011: a 's'-fragment detector.

It goes negative on a token that is a bare split-off plural or abbreviation tail:
a lone letter s/S (as in "GS" split as "G"+"S", "FIG. 2" -> "FIG" + "S", or
"Tom" + " s"), a consonant+s piece ("bs", "ps", "cs"), or an all-caps acronym ending
in S ("BS", "PS", "GS", "CS"). Possessive 's and ordinary words ending in s
(is, as, was, has, this) are left at zero, because the component does not respond to them.
"""
READS = ()

CONSONANTS = set("bcdfghjklmnpqrstvwxyz")
CAPS_CONSONANTS = set("BCDFGHJKLMNPQRSTVWXYZ")


def core(token):
    """The token with its leading spaces and punctuation removed."""
    i = 0
    while i < len(token) and not token[i].isalpha():
        i += 1
    return token[i:]


def predict(token):
    if token[:1] in "'’":
        return 0.0
    c = core(token)
    if c == "s":
        return -1.0 if token[0] != " " else -1.1
    if c == "S":
        return -1.3
    if len(c) == 2 and c[0] in CONSONANTS and c[1] == "s":
