READS = ()
CHAT_BOUNDARIES = {
    '<|endoftext|>': -0.011, '<|im_start|>': -0.043, '<|im_end|>': -0.002,
    '<tool_call>': -0.050, '</tool_call>': 0.087,
    '<tool_response>': -0.031, '</tool_response>': -0.135,
    '<think>': -0.087, '</think>': 0.161,
}
NOTATION = {'+-': 0.80, '²': 0.18, '³': 0.12, 'º': 0.43, '§': 0.35}
DOCUMENT_WORDS = {
    'document': -1.11, 'documents': -1.18, 'docs': -0.56, 'doc': -0.20,
    'documentation': -0.46, 'corpus': -0.69, 'literature': -0.46,
    '文档': -0.82, '文献': -1.10, 'документ': -0.61, 'документов': -0.99,
}
FREQUENCY_WORDS = {
    'usually': 0.70, 'sometimes': 0.61, 'occasional': 0.42,
    'occasionally': 0.33, 'mostly': 0.26, 'normally': 0.15, 'typically': 0.11,
}
UNCERTAINTY_WORDS = {
    'uncertain': 0.70, 'uncertainty': 0.54, 'uncertainties': 0.40,
    'unsure': 0.43, 'likely': -0.22, 'unlikely': -0.18,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    spaced = token[:1].isspace()
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip()
    lower = word.lower()
    value = NOTATION.get(word, CHAT_BOUNDARIES.get(word, 0.0))
    if word in {'±', '+/-'}:
        value = 4.60 if spaced else 5.20
        if word == '+/-':
            value = 4.23
        elif previous.lower() in {'mean', 'means'}:
            value = 5.30
    elif word in {'°', '°C', '°F'}:
        value = 1.15 if spaced else 1.35
        if len(word) > 1:
            value = 0.55 if word[-1] == 'C' else 0.65
    elif word in {'μ', 'µ'}:
        value = 0.66 if spaced else 0.69
        if word == 'µ':
            value = 0.40 if spaced else 0.52
        elif not spaced and previous and '\u0370' <= previous[-1] <= '\u03ff':
            value = 0.36
    elif word in {'pm', 'PM'}:
        value = 1.29 if word == 'PM' else (1.54 if spaced else 2.10)
        if word == 'pm' and previous.endswith('\\'):
            value = 3.10
    elif word in {'©', '®'}:
        value = 1.02 if word == '©' else (0.53 if spaced else 0.23)
        if word == '©' and '\ufffd' in previous:
            value = 0.30
    elif lower in FREQUENCY_WORDS:
        value = FREQUENCY_WORDS[lower]
        if lower == 'usually':
            value += 0.24 * (not spaced) - 0.18 * word[0].isupper()
        elif lower == 'sometimes' and word[0].isupper():
            value = 0.55
    elif lower in UNCERTAINTY_WORDS:
        value = UNCERTAINTY_WORDS[lower]
    else:
        noun = lower.lstrip('._/=(')
        if noun in DOCUMENT_WORDS:
            value = DOCUMENT_WORDS[noun]
            if noun in {'document', 'documents'}:
                if word[:1] in '.(':
                    value = -0.81
                elif word.istitle() and not spaced:
                    value = -1.74
                elif previous == '$(':
                    value = -1.70
    return None, float(value)

