"""A lexical dis- / separation signal, strongest on the bare prefix.

English dis- words are positive, especially explicit removal, negation, and
separation. Several common words that only happen to start with those letters
are weaker. A few Chinese scattering, separation, and disk forms are included.
The bare prefix is stronger when capitalized or at a document start. A small
response persists on its immediate continuation; document boundaries reset it.
"""
READS = ()


def english(word):
    lower = word.lower()
    if lower == 'dis':
        return 5.4 if word == 'Dis' else 4.5 if word == 'DIS' else 4.8
    if lower.startswith('dys'):
        return 1.7 if lower == 'dys' else 0.8
    if not lower.startswith('dis'):
        return 0.0
    if lower.startswith(('disab', 'disconnect', 'discount', 'disjoint',
                         'disord', 'disqual', 'dispers', 'discret')):
        return 3.1
    if lower in ('disp', 'displ', 'disse'):
        return 3.1
    if lower.startswith(('disagree', 'disappoint', 'discharg', 'disclaim',
                         'discontin', 'dismiss', 'displac', 'dispos',
                         'dissent', 'dissect', 'dissoci')):
        return 2.2
    if lower.startswith(('discuss', 'distrib', 'distingu', 'distress')):
        return 0.3
    if lower.startswith(('disclos', 'discrimin', 'disease', 'dish',
                         'display', 'dissolv')):
        return 0.7
    if lower.startswith(('distance', 'discover', 'disrupt', 'dispatch')):
        return 1.6
    return 1.2


