    token = prefix.token_strings[-1]
    # Ignore whitespace and programming punctuation attached before the word.
    word = token.lstrip(' \t\r\n_-./(\"\'')
    document = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != document
    previous_bare_prefix = False if fresh else carry[1]
    value = english(word)
    if word.lower() == 'dis' and fresh:
        value += 2.5
    elif previous_bare_prefix and token.isalpha():
        value = max(value, 0.9)
    if token == '散':
        value = 7.0
    elif '散' in token:
        value = 2.2
    elif token in ('离', '離', '分歧', '处置'):
        value = 1.8
    elif token in ('失', '盘', '盤'):
        value = 1.1
    elif word.lower().startswith('scatter'):
        value = 1.1
    return (document, word.lower() == 'dis'), value

