"""Detects the English prefix 'dis-' (and a few dispersal words) in the current token.

It fires on the bare fragment "dis" most strongly, on dis- words that carry the
negation/apart sense (disable, disorder, discount...) moderately, on other dis-
words weakly, and on near-synonyms of "disperse" (scatter, 散). Common words that
only look like they start with dis- (disease, dish, discuss, distribution) are
near zero.
"""
READS = ()

BARE = {"dis"}
NEGATION = {
    "disable", "disabled", "disabling", "disability", "disabilities", "disorder",
    "disorders", "disconnect", "discount", "discounts", "discrete", "discharge",
    "dismiss", "dismissed", "disagree", "disrupt", "disrupted", "disrupting",
    "disposed", "dispersion", "disappointed", "displaced", "displacement",
}
FALSE_FRIENDS = {
    "disease", "dish", "dishes", "distribution", "distributions", "distribute",
    "discuss", "discussed", "discussion", "discussing", "discusses", "discussions",
    "distinguish", "distinguished", "distinction", "distinctly", "distress", "dissolved",
}
DISPERSE = {"scatter", "scattered", "scattering", "散", "疏散", "分散", "离", "離", "divorce"}


