"""A partial local-pattern approximation, not a single semantic topic.

Strong positives mark the endings of Fairbanks, Salzburg, NetCDF, 便携 and 交尾,
and two common English formulae. Weaker rules cover partitive constructions,
auxiliaries, a few software paths, and token shape. Opening markup is negative.
The many other token-specific fluctuations are deliberately not memorized.
"""
READS = ()
QUANTIFIERS = {'all', 'some', 'most', 'any', 'none'}
COLLECTIONS = {'set', 'list', 'range', 'variety', 'series', 'group',
               'collection', 'combination'}


def response(position, older, previous, token):
    word, before = token.strip().lower(), previous.strip().lower()
    if position == 0:
        if word.startswith(('#', '//', '/*')) or word in {'import', 'class'}:
            return -0.132
        if word and set(word) == {'-'}:
            return -0.114
    if token == 'banks' and previous.endswith('Fair'):
        return 0.60
    if token == 'zburg' and previous.endswith('Sal'):
        return 0.48
    if token in {'cdf', 'CDF'} and previous.lower().endswith('net'):
        return 0.60
    if token == '携' and previous.endswith('便'):
        return 0.73
    if token == '尾' and previous.endswith('交'):
        return 0.60
    if word == 'comes' and before == 'it':
        return 0.38 if older.strip().lower() == 'when' else 0.12
    if word == 'noted' and before == 'be':
        return 0.38 if older.strip().lower() == 'should' else 0.08
    if token == '/null' and previous.endswith('dev'):
        return 0.38
    if token == '_modules' and previous.endswith('node'):
        return 0.10
    if token == 'www' and previous.endswith('://'):
        return 0.145
    if word == 'of':
        if before in QUANTIFIERS:
            return 0.10
        if before in COLLECTIONS:
            return -0.075
        if before == 'part':
            return 0.075
    if word in {'be', 'have'} and before in {'will', 'shall', 'should'}:
        return 0.045 if before == 'should' else -0.059
    if word in {'have', 'has'}:
        return -0.027
    if word in {'could', 'would', 'should', 'may', 'might', 'must'}:
        return 0.024
    if word in {'can', 'will'}:
        return -0.012
    if token.isspace():
        if '\n' in token:
            return 0.04 if position == 0 else 0.002 + 0.012 / (1 + position / 32)
        return 0.006 - len(token) * 0.001
    if word.isascii() and word.isalpha():
        value = 0.0065 - 0.0008 * min(len(word), 12)
        value -= 0.003 * token.startswith(' ')
        value -= 0.0033 * token.strip().istitle()
        value -= 0.004 * token.strip().isupper()
        for ending, change in (('ly', -0.01), ('ness', 0.014),
                               ('ing', 0.004), ('s', 0.003)):
            if len(word) > len(ending) + 1 and word.endswith(ending):
                value += change
        return value
    return 0.0021 if word.isdigit() else -0.0003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, older, previous = 0, '', ''
    else:
        _, position, older, previous = carry
    token = prefix.token_strings[-1]
    value = response(position, older, previous, token)
    return (doc, position + 1, previous, token), float(value)

