programs.sol:
"""Common separators and grammatical glue near document openings.
After a separate first-token estimate, the negative response rises briefly
and then fades with document length, repeated instances of the text class,
and preceding boundaries. Script-specific sentence punctuation is stronger;
numbers and adjacent separators weaken most responses. Ordinary word pieces
are near zero. Class averages deliberately omit lexical idiosyncrasies.
"""
import math
READS = ()

import unicodedata
from functools import lru_cache

GLUE = set(('to in for from at by as with on of that or but if which this '
            'these those there their was were be been being has have had').split())

@lru_cache(maxsize=8192)
def category(text):
    s = text.strip()
    if '\ufffd' in text:  # Incomplete UTF-8 pieces have no reliable character class.
        return 'word'
    if text.startswith('<|') or s.startswith('<tool_'):
        return 'special'
    if not s:
        if '\n' in text and not ('\t' in text or text.count(' ') > 1):
            return 'paragraph' if text.count('\n') > 1 else 'newline'
        return 'space' if text == ' ' else 'indent'
    if s in {'，', '،'}:
        return 'wide_comma'
    if s == '。':
        return 'wide_period'
    if s in {'、', '：', '；', '！', '？', '）', '」', '』'}:
        return 'wide_other'
    if all(unicodedata.category(c)[0] in 'PS' for c in s):
        if text[0].isspace():
            return 'spaced_punctuation'
        if s.count('.') > 1:
            return 'ellipsis'
        if '.' in s and set(s) <= set('.)\'"”’]'):
            return 'period'
        if ';' in s or ('\n' in text and s in {'"', "'"}):
            return 'semicolon'
        if ':' in s:
            return 'colon'
        if ',' in s and set(s) <= set(',)\'"”’]'):
            return 'comma'
        if s in {')', ']', '))', ']]', '”'} or '\n' in text:
            return 'close'
        if s in {'?', '!'}:
            return 'question'
        return 'punctuation'
    if text.startswith(' '):
        w = s.lower()
        if w in {'the', 'and'}:
            return w
        if w in {'a', 'an'}:
            return 'article'
        if w in {'is', 'are'}:
            return 'be'
        if w in GLUE or s in {"'s", '’s'}:
            return 'glue'
    if s in {'的', 'の', 'は'}:
        return 'east_asian_grammar'
    return 'number' if s.isdigit() else 'word'

BOUNDARIES = {'period', 'comma', 'colon', 'semicolon', 'close', 'question',
              'newline', 'paragraph', 'wide_period', 'wide_comma', 'wide_other'}

def modifiers(k, text, numeric, boundary, whitespace, role):
    factor = 1.0
    if k == 'the' and text.strip() == 'The':
        factor *= .55
    lines = text.count('\n')
    if lines:
        if k in {'period', 'wide_period'}:
            factor *= .9 if lines == 1 else .7
        elif k in {'comma', 'colon'}:
            factor *= .7
        elif k == 'semicolon':
            factor *= 1.5
    if numeric and k in BOUNDARIES | {'the'}:
        factor *= .65
    if boundary and k in {'period', 'comma', 'close', 'space', 'the', 'and',
                          'article', 'glue', 'spaced_punctuation'}:
        factor *= .5 if k == 'period' else .65
    if whitespace:
        if k == 'newline':
            factor = 0
        elif k in {'paragraph', 'semicolon', 'close'}:
            factor *= .5
        elif k in {'space', 'article', 'glue', 'and', 'be',
                   'spaced_punctuation', 'punctuation'}:
            factor *= .65
    if role and k == 'newline':
        factor *= 1.2
    return factor


def repetition_weights(k):
    if k in {'wide_comma', 'wide_period', 'wide_other', 'east_asian_grammar'}:
        return .3, 0
    if k in {'article', 'glue', 'be', 'and', 'punctuation',
             'spaced_punctuation', 'ellipsis', 'newline', 'paragraph'}:
        return .1, .5
    return (.1, .15) if k == 'space' else (.3, .15)

# Baseline, strength, distance scale, rise time, initial-token value.
PARAMETERS = {
    'and': (0.15, -2.89, 40, 1, -0.15),
    'article': (0.12, -1.52, 20, 1, -0.17),
    'be': (0.12, -1.88, 20, 1, -0.55),
    'close': (0.08, -2.94, 160, 1, -0.54),
    'colon': (0.12, -2.19, 80, 0.5, -0.38),
    'comma': (0.03, -3.81, 160, 1, -0.7),
    'east_asian_grammar': (0.09, -3.66, 10, 0.5, -0.64),
    'ellipsis': (0.06, -1.77, 100000, 1, 0.06),
    'glue': (0.05, -0.72, 20, 0.5, -0.28),
    'indent': (0.14, -0.98, 640, 0.5, -0.76),
    'newline': (-0.37, -4.46, 640, 1, -0.63),
    'number': (0.01, -0.41, 5, 1, -0.18),
    'paragraph': (-0.08, -3.49, 100000, 2, -0.1),
    'period': (-0.1, -4.26, 100000, 2, -0.68),
    'punctuation': (0.08, -1.04, 160, 0.5, -1.69),
    'question': (0.17, -2.97, 160, 0.5, -0.63),
    'semicolon': (-0.12, -2.97, 80, 1, -0.8),
    'space': (0.26, -2.64, 640, 0.5, -0.85),
    'spaced_punctuation': (0.09, -1.64, 40, 1, -0.38),
    'special': (-0.07, 0.66, 5, 0.5, 0.88),
    'the': (0.24, -2.87, 80, 1, -0.59),
    'wide_comma': (-0.2, -5.49, 40, 1, -0.63),
    'wide_other': (0.11, -4.0, 20, 0.5, -0.45),
    'wide_period': (-0.23, -6.54, 40, 2, -0.65),
    'word': (-0.01, -0.03, 5, 0.5, -0.4),
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:  # Attention resets here too.
        position, counts, boundaries = 0, {}, 0
        previous_number = previous_boundary = previous_space = previous_role = False
    else:
        (_, position, counts, boundaries, previous_number,
         previous_boundary, previous_space, previous_role) = carry
        position += 1
    text = prefix.token_strings[-1]
    k = category(text)
    base, strength, scale, rise, initial = PARAMETERS[k]
    repeat, boundary = repetition_weights(k)
    denominator = 1 + position / scale
    denominator += repeat * counts.get(k, 0) + boundary * boundaries
    fading = (1 - math.exp(-position / rise)) / denominator
    fading *= modifiers(k, text, previous_number, previous_boundary,
                        previous_space, previous_role)
    value = initial if position == 0 else base + strength * fading
    counts[k] = counts.get(k, 0) + 1
    boundaries += k in BOUNDARIES
    carry = (doc, position, counts, boundaries, text.strip().isdigit(),
             k in BOUNDARIES, not text.strip(),
             text in {'user', 'system', 'assistant'})
    return carry, float(value)

