    # Recover a completed character split into byte-level tokens.
    if '\ufffd' in token:
        text = prefix.text_prefixes[-1]
        if text and text[-1] != '\ufffd':
            before = prefix.text_prefixes[-2] if prefix.position else ''
            tail = text[len(before.rstrip('\ufffd')):]
            if tail:
                token = tail
    letters, word = spelling(token)
    old, oldword = spelling(previous)
    n = len(letters)
    has_p = any(c in P_LETTERS for c in letters)
    spaced = bool(token) and token[0].isspace()
    value = -0.001

    if 'π' in word:
        value = -1.80
    elif word == 'п':
        value = -1.25 if letters.isupper() else -0.93
    elif word == 'пи':
        value = -1.45
    elif n == 1 and letters in PI_CHINESE:
        value = -1.18
    elif has_p:
        if n == 1 and letters[0] not in 'pPпП':
            # Pi-like syllables are stronger than pu-like syllables.
            if letters in 'プぷ프푸플':
                value = -0.15
            elif letters == 'پ':
                value = -1.18
            elif letters in 'ポぽ포พ':
                value = -0.45
            else:
                value = -0.85
        elif n == 1:
            value = -0.27 if spaced else -0.05
            if token in ('.p', '.P', '_p', '_P'):
                value = -0.24
        elif word == 'pi':
            value = -0.88
        elif word == 'pe':
            value = -0.62
        elif n <= 3 and word.startswith('pp'):
            value = -0.57
        elif word.startswith(('pip', 'pap', 'pep', 'pop', 'поп')) and n <= 6:
            value = -0.95 if word.startswith('pip') else -0.72
        elif n <= 3 and ('pi' in word or 'pe' in word):
            value = -0.22
        elif word in ('pa', 'py'):
            value = -0.27
        elif word == 'po':
            value = -0.10

    if start and has_p and 'π' not in word:
        if token == 'П':
            value = -5.58
        elif token == 'P':
            value = -3.70
        elif token == 'p':
            value = -3.09
        elif word in ('p', 'pi', 'pe', 'ap', 'ep'):
            value = -2.65
        elif n <= 2:
            value -= 0.65
        elif n == 3 and word.startswith(('pi', 'pe')):
            value -= 0.60

    if any(c in P_LETTERS for c in old[-3:]):
        value += continuation(letters, word, old, oldword, token, has_p)
        caps_cluster = (has_p and n <= 3 and letters.isupper()
                        and old.isupper() and len(old) <= 3
                        and old[-1] in P_LETTERS and token[0].isalpha())
        if caps_cluster:
            value -= 0.60

    return (doc, token), float(value)


def continuation(letters, word, old, oldword, token, has_p):
    """Extra response to spelling continued from a nearby p."""
    n = len(letters)
    if old[-1] not in P_LETTERS:
        return -0.14 if has_p else -0.005
    if n and letters[-1] in P_LETTERS:
        if len(old) > 3:
            return -0.27
        return -1.89 if n <= 2 else -0.85
    if word and word[0] in VOWELS:
        if token[0].isspace():
            return -0.06
        if n >= 3:
            return -0.56 if word[0] in I_Y else -0.21
        if word[0] in 'oо':
            return -0.37
        if not token[0].isalnum():
            return -0.20
        if n == 1:
            return -1.82 if word[0] in I_Y else -1.19
        return -0.79
    if n and letters[0] in P_LETTERS:
        if n >= 4:
            return -0.40
        return -1.95 if len(old) <= 2 else -0.89
    if 'π' in oldword:
        return -0.80 if n else -0.04
    if not n:
        return -0.08
    if 'п' in oldword:
        return -0.65 if n <= 2 else -0.16
    return -0.03

programs.haiku:
"""Layer-0 MLP down-projection component 5018: a "p / pi" letter detector.

The component's activation is negative when the current token is a "p-sound" letter:

1. a lone Greek pi or Cyrillic pe (π, п, and capitals Π, П): about -1.5 to -1.8;
2. a whole token spelled like "pi" / "pe" (pi, PI, pe, pipe, ps, pp): about -0.5 to -1.0;
3. a lone Latin p or P: about -0.1 to -0.4;
4. a word continued after a token that ends in p (the "i" of "Pi", the "ino" of "P|ino",
   the "f" of "op|f"; no space before it): about -0.4.

It is a little more negative when a p-like token opens a new document (it follows
<|endoftext|>, where the largest responses occur), about -2.5. Everything else is ~0.

Program state: none beyond the previous token and the document boundary, read from the
newest token and the document ids, as the model resets at each document.
"""

READS = ()

# the Greek small pi and the Cyrillic small pe, in either case (π, Π, п, П)
PI_LETTERS = {"π", "п"}
# whole tokens with the "pi" / "pe" sound
PI_WORDS = {"pi", "pe", "pipe", "ps", "pp"}
# the Latin letter p on its own
P_LETTER = {"p"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip().lower()
    docs = prefix.document_ids
    new_doc = len(docs) > 1 and docs[-1] != docs[-2]
    if token in PI_LETTERS:
        value = -1.5
    elif token in PI_WORDS:
        value = -0.5
    elif token in P_LETTER:
        value = -0.1
    elif len(docs) > 1 and not new_doc and raw[:1].isalpha():
        # a word piece with no space before it, after a piece ending in p
        if prefix.token_strings[-2][-1:] in ("p", "P"):
            value = -0.4
        else:
            return None, 0.0
    else:
        return None, 0.0
    if new_doc:
        value = -2.5
    return None, value

"""layers.0.mlp.down_proj:5019 -- "adjective completion" feature.

What it does: this component fires on the piece of text that finishes an adjective
(or the word right after one that completes a comparison or degree phrase):

* Japanese adjective endings after a kanji stem: 痛い, 寒い, 簡単な, 忙しく, 大きかった,
  痛くなる. The ending い, な, く, しく, さ, かった fires hardest.
  Verb and particle endings (して, ている, を, の) fire weakly or not at all.
* English degree words after an adjective: "clumsy enough", "old enough", "as simple as"
  (the second "as"), "more efficient than", "special ones", "silent nature", "-ness".
* Vietnamese and Chinese comparatives after an adjective: hơn, nhất, 一点.

It predicts a fixed level for each such token and about zero everywhere else.
The adjective test uses a short list of common English adjectives plus suffixes.

Simple version: a token-class lookup. What it misses: most of the variance is spread over many
rare tokens in several languages, and the negative dips are not modelled.
"""
import unicodedata

READS = ()

ADJECTIVES = set("""
big small large little old young new high low long short good bad great far close near
angry clumsy versatile interesting true strong weak cool slow fast quick hot cold cheap sure
ready easy hard simple soft loud fine late early wide deep thin thick rich poor safe strict
tight dull abundant patient honest happy sad busy tall full empty heavy light dark bright
clear difficult special unique complicated complex nervous keen wrong right free sharp
""".split())

# Japanese adjective endings and their typical strength after a kanji stem.
ADJ_ENDING = {"い": 3.0, "な": 2.8, "しく": 3.4, "かった": 2.8, "くな": 5.0,
              "くなる": 3.3, "くなった": 2.5, "く": 1.5, "さ": 1.7, "しい": 2.8}
# Verb endings after a kanji stem: weaker.
VERB_ENDING = {"して": 0.6, "する": 0.6, "ている": 0.6, "ない": 0.7, "し": 0.7}


def is_kanji(ch):
    return "CJK" in unicodedata.name(ch, "")


def is_hiragana(ch):
    return "HIRAGANA" in unicodedata.name(ch, "")


def adjective_like(word):
    w = word.strip().lower()
    return w in ADJECTIVES or w.endswith(("ful", "ous", "ble", "ive", "ish", "less", "ic"))


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    prev = s[-2] if len(s) > 1 else ""
    prev2 = s[-3] if len(s) > 2 else ""
    if cur == " enough":
        return None, (3.5 if adjective_like(prev) else 0.4)
    if cur == " than":
        return None, (1.2 if adjective_like(prev) or prev.strip() in ("more", "less") else 0.3)
    if cur == "ness":
        return None, 1.1
    if cur in (" ones", " nature", " one", " about") and adjective_like(prev):
        return None, 1.2
    if cur == " as" and prev2.strip() == "as" and adjective_like(prev):
        return None, 1.5
    if cur == " nhất":
        return None, 2.5
    if cur == " hơn":
        return None, 4.0
    if cur in ADJ_ENDING and prev:
        return None, ADJ_ENDING[cur] if is_kanji(prev[-1]) else 0.5 * ADJ_ENDING[cur]
    if cur in VERB_ENDING and prev and is_kanji(prev[-1]):
        return None, VERB_ENDING[cur]
    if cur and is_hiragana(cur[0]) and prev and is_kanji(prev[-1]):
        return None, 0.3
    if cur and is_hiragana(cur[0]) and prev and is_hiragana(prev[-1]):
        return None, 0.1
    return None, 0.0

"""Layer-0 MLP neuron 5020 (down_proj, feature 5020) reads words that mark a limit in time
("until", "till", "hasta", "jusqu'à"), an exception ("unless", "except"), or a starting point
("since", "desde", "before"), plus "either", "including" and "up to" / "prior to"."""
READS = ()

LIMIT_WORDS = {
    "until": 8.0, "till": 4.3, "til": 2.0, "unless": 3.9, "except": 1.8, "excluding": 0.8,
    "since": 1.2, "before": 0.6, "either": 0.9, "including": 0.7, "up": 0.3, "through": 0.3,
    "hasta": 5.5, "até": 5.5, "jusqu": 5.8, "fino": 3.8, "bis": 2.2, "desde": 1.8,
    "depuis": 1.6, "до": 1.7, "到": 1.5, "至": 1.9, "đến": 0.8, "自": 0.9, "及": 0.9,
    "para": 0.7, "upto": 3.8,
}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word == "to" and prev in ("up", "prior", "back", "down"):
        return carry, 1.0
    if word in ("à", "’à", "'à") and prev == "jusqu":
        return carry, 4.0
    return carry, float(LIMIT_WORDS.get(word, 0.0))

programs.sol:
"""A lexical relation-marker detector, mainly English 'in' and Chinese 在.

Location/time prepositions, object particles and opening square brackets have
smaller responses. Capitalization and word boundaries matter. Common governed
complements ('interested in', 'based on', 'look at') suppress the response.
Chinese compounds for 'now', 'existence', or 'potential' also weaken it.
This remembers only the previous token, resetting at document boundaries;
it does not parse sentences or model weaker, unrelated vocabulary effects.
"""
READS = ()

# Location/time words, including translations of 'in'.
PREPOSITIONS = {
    'within': 1.0, 'during': 0.8, 'inside': 0.7, 'outside': 0.6,
    'between': 0.5, 'throughout': 0.55, 'around': 0.4,
    'across': 0.45, 'along': 0.4, 'behind': 0.3,
    'en': 0.33, 'em': 0.26, 'dans': 0.55, 'bei': 0.57,
    'в': 0.7, 'во': 0.6, 'في': 0.9,
}
# Chinese relational words: origin, direction, means, passive, accompaniment.
CHINESE_RELATIONS = {
    '自': 1.1, '从': 0.6, '向': 0.8, '对': 0.85, '對': 0.85,
    '于': 0.6, '於': 0.6, '位于': 2.5, '以': 0.75, '被': 1.1,
    '为': 0.4, '為': 0.4, '到': 0.45, '由': 0.45, '用': 0.4,
    '与': 0.4, '與': 0.4, '和': 0.25,
}


def location_compound(s):
    if s.startswith(('现在', '現在', '到现在', '到現在')):
        return 1.2 if s in {'现在', '現在'} else 0.35
    if '存在' in s:
        return 2.9 if s.endswith('于') else 0.45
    if '潜在' in s:
        return 1.0
    if s in {'在一起', '在于', '在哪里', '在这里', '旨在', '自在'}:
        return 2.5
    if s == '在线':
        return 4.3
    if s == '在' or s.startswith(('，在', ',在')):
        return 6.5
    if s.startswith('在'):
        return 5.8
    if s.startswith(('坐', '站', '躺', '放', '出现', '所', '停留',
                     '生活', '发生', '集中')):
        return 3.7
    if s.startswith(('是', '就是', '就', '正')):
        return 4.3
    return 5.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous_token = '' if start else carry[1]
    previous = previous_token.strip().lower()
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('._/-,')
    word = spelling.lower()
    boundary = token[:1].isspace() or token[:1] in '._/-,'
    value = 0.0
    if '在' in token:
        value = location_compound(token.strip())
        if token[:1].isspace():
            value -= 1.1
    elif token.strip() in CHINESE_RELATIONS:
        value = CHINESE_RELATIONS[token.strip()]
    elif 'を' in token:
        value = 1.1 if token.endswith('を') else 0.55
    elif token.strip().endswith(('을', '를')):
        value = 0.95
    elif word == 'in':
        value = 1.45 if boundary else 1.15
        if not boundary and previous_token[-1:].isalnum():
            value = 0.15
        if spelling == 'In':
            value = 2.9 if start else 1.7
        elif spelling == 'IN':
            value = 1.1 if boundary else 0.33
        elif previous in {'interested', 'resulted', 'resulting'}:
            value = 0.1
        elif previous in {'result', 'results', 'involved'}:
            value = 0.45
        elif previous in {'engaged', 'interest', 'invest'}:
            value = 0.65
        elif boundary and (previous.endswith('ed') or previous in {'found', 'shown'}):
            value = 1.1
        elif boundary and previous in {',', ';', ':'}:
            value = 1.6
    elif word == 'on':
        value = 0.9 if spelling == 'On' else (0.5 if boundary else 0.08)
        if previous.startswith(('depend', 'focus', 'rely')) or previous == 'based':
            value = -0.1
    elif word == 'at':
        value = 0.3 if boundary or spelling == 'At' else 0.0
        if previous in {'look', 'looks', 'looking', 'looked', 'attempt'}:
            value = -0.1
    elif word in PREPOSITIONS:
        value = PREPOSITIONS[word]
        if word in {'en', 'em', 'в'} and not boundary:
            value *= 0.25
    elif '∈' in token:
        value = 0.85
    elif '[' in token and ']' not in token:
        value = 0.5
        if '#' in token:
            value = 1.2
        elif any(c.isupper() for c in token):
            value = 0.8
        elif any(c.islower() for c in token):
            value = 0.15
    return (doc, token), float(value)

programs.luna:
"""Approximate a sparse set of lexical cues with fixed activation values.

The sampled strong responses repeatedly included English “in,” with smaller
responses on “at” and “on.” Other positive examples included “within,” the
Chinese character 在, the Japanese particle を, and an opening square bracket.
This simple detector uses those token cues and ignores surrounding context.
"""
READS = ()

IN_WORDS = {"in", "In"}
AT_WORDS = {"at", "At"}
ON_WORDS = {"on", "On"}
OTHER_SPATIAL_WORDS = {"within", "Within", "into", "Into"}
JAPANESE_OBJECT_PARTICLES = {"を"}
OPENING_BRACKETS = {"["}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in IN_WORDS:
        value = 1.4
    elif word in AT_WORDS:
        value = 0.45
    elif word in ON_WORDS:
        value = 0.65
    elif word in OTHER_SPATIAL_WORDS:
        value = 1.0
    elif "在" in word:
        value = 2.5
    elif word in JAPANESE_OBJECT_PARTICLES:
        value = 0.8
    elif word in OPENING_BRACKETS:
        value = 0.55
    else:
        value = 0.0
    return None, value

programs.haiku:
"""layers.0.mlp.down_proj:5023: a "weighing / discussing / thinking about" detector.

What it does: this component writes into the residual stream when the text names an
act of considering, discussing or thinking about something. It is strongest on the
word "consider" and its forms ("consider", "considered", "considering",
"consideration(s)", "reconsider"; also "reconsideration", "deliberation",
"contemplation" through their suffix). It is somewhat weaker on discuss, debate,
discussion, deliberate, and on the non-English words for those ideas (Chinese
思/討/議/論/談/慮, Russian думать, рассмотреть, обсудить).

Weaker still on explore, investigate, examine, ponder, talk, think, thought,
thinking, and on topic-of-talk nouns (topic, issue, conversation, concern,
regarding, address, review). The preposition that introduces the object of such
a verb ("think ABOUT", "think OF", "look AT", "comment ON", "consideration OF")
fires too, and "about" fires on its own at a lower level. Legal-contract words
(contract, agreement, affidavit, testimony) push it slightly negative.

Everything else predicts 0. The program looks only at the current token and the
one before it, so it needs no carried state. Values are rough means of the
component's activation on sampled text, not fitted weights.
"""

READS = ()

CONSIDER = {"consider", "considers", "considered", "considering", "consideration",
            "considerations", "reconsider"}
DISCUSS = {"discuss", "discussed", "discusses", "discussing", "discussion", "discussions",
           "debate", "debates", "debated", "deliberate", "deliber"}
MULTILINGUAL = {"думать", "дум", "рассм", "обсужд", "consid", "討", "議", "思", "慮", "考虑",
                "讨论", "议论", "思考", "热议", "談", "谈", "論", "论"}
THINK = {"explore", "investigate", "examine", "ponder", "talk", "talks", "talking", "talked",
         "thoughts", "thinking", "think", "thought", "contemplate"}
TOPICS = {"topic", "topics", "issue", "issues", "conversation", "conversations", "regarding",
          "address", "review", "negotiations", "concern", "concerns"}
LEGAL = {"contract", "contracts", "agreement", "agreements", "affidavit", "testimony",
         "cooperation"}
VERB_BEFORE_OBJECT = CONSIDER | DISCUSS | THINK | {"look", "looking", "looked", "looks",
                                                   "comment", "comments"}
STEMS_BEFORE_SUFFIX = {"consider", "reconsider", "deliber", "contempl"}
PREPOSITIONS = {"about", "of", "on", "at", "upon", "over", "regarding"}


def word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = word(s)
    prev = word(prefix.token_strings[-2]) if len(prefix) > 1 else ""
    if w in CONSIDER:
        v = 2.3
    elif w in DISCUSS or w in MULTILINGUAL:
        v = 1.5
    elif w in THINK or w in TOPICS:
        v = 0.5
    elif w in ("ation", "ations") and prev in STEMS_BEFORE_SUFFIX:
        v = 2.5
    elif w in LEGAL:
        v = -0.4
    elif w in PREPOSITIONS and prev in VERB_BEFORE_OBJECT:
        v = 1.0
    elif w == "about":
        v = 0.5
    else:
        v = 0.0
    return carry, float(v)

programs.sol:
"""Pulses on vocabulary of effects, efficiency, validity, and equivalence.

These are lexical signals, not an assessment of whether something works.
Effect words in Chinese, Japanese, Korean, and Russian are included. Local
phrases distinguish side effects, no effect, and being in effect. A brief
continuation covers split word endings and following prepositions. Tool-message
endings have a separate small response. State resets at each new document.
"""
READS = ()

# Approximate strengths shared by closely related words and word fragments.
WORD_GROUPS = (
    (2.4, 'effect'),
    (2.5, 'equivalent'),
    (2.2, 'efficiency effectiveness effic'),
    (1.8, 'effects effective efficacy ineffective ineff ivalent useeffect'),
    (1.5, 'efficient efficiently effectively inefficient efficiencies equivalents'),
    (1.3, 'affect equivalence ffect ffective ffects ivalence'),
    (1.1, 'affects affected affecting eff valid validity equival'),
    (0.7, 'impact impacts impacted impacting impactful invalid unaffected '
          'afect helper'),
    (0.9, 'effected'),
    (0.95, 'analogous'),
    (0.4, 'ef equiv utility util'),
    (0.2, 'usage outcome outcomes benefit beneficial successful successfully '
          'achieve alternative alternatively operative'),
)
WORDS = {word: value for value, group in WORD_GROUPS for word in group.split()}

# Chinese effect vocabulary: single character, compounds, and longer phrases.
CHINESE_GROUPS = (
    (8.4, ('效',)),                         # effect / efficacy
    (2.6, ('效果', '有效', '生效', '成效', '功效')),
    (3.8, ('效率', '高效', '效益', '效应')),  # efficiency / benefit
    (4.6, ('效能', '实效')),                # efficacy / practical effect
    (1.4, ('特效', '绩效')),                # special effects / performance
    (3.3, ('无效',)),                       # invalid / ineffective
)
CHINESE = {word: value for value, group in CHINESE_GROUPS for word in group}

# Function, influence, quality, consumption, value, achievement, and synergy.
RELATED_CHINESE = frozenset('影响 作用 良 耗 价 価 價 价值 佳 达成 协同'.split())

# Qwen's token for UTF-8 E5 8A, shared by 効 (effect), 労 (labor), 力 (force).
# This incomplete character has a pulse even before its last byte arrives.
KANJI_FORCE_PREFIX = 8079


def strength(raw):
    word = raw.strip().strip('._-()').lower()
    value = WORDS.get(word, 0.0)
    if raw.strip().startswith('-') and word.startswith('eff'):
        value += 0.55
    if '效' in word:
        value = CHINESE.get(word, 2.8)
        if word not in CHINESE:
            for compound, pulse in CHINESE.items():
                if len(compound) == 2 and compound in word:
                    value = 0.85 * pulse
                    break
    elif word in RELATED_CHINESE:
        value = 0.7
    elif word == '能':
        value = 0.3
    elif word == '効':
        value = 4.9
    elif word in {'효', '효과', 'hiệu'}:
        value = {'효': 4.0, '효과': 3.2, 'hiệu': 2.3}[word]
    elif word.startswith('эффектив'):
        value = 2.9
    elif word == 'эфф':
        value = 1.9
    elif word in {'efect', 'effet', 'effetti', 'efecto', 'effekt'}:
        value = 1.0
    return word, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, old_value, tail = '', 0.0, ''
    if carry is not None and carry[0] == doc:
        previous, old_value, tail = carry[1:]
    raw = prefix.token_strings[-1]
    word, value = strength(raw)
    if prefix.token_ids[-1] == KANJI_FORCE_PREFIX:
        value = 1.77
    if '\ufffd' in raw:
        final = prefix.text_prefixes[-1][-1:]
        if final in {'效', '効'}:
            word, value = strength(final)
    # Secondary effects are weaker; the phrase 'in effect' is stronger.
    if word in {'effect', 'effects'} and previous == 'side':
        value *= 0.62
    elif word == 'effect' and previous == 'in':
        value = 2.9
    elif word == 'effect' and previous == 'no':
        value = 2.15
    if word == '<|im_end|>':
        tool_end = tail.rstrip().endswith(('</tool_call>', '</tool_response>'))
        value = 0.4 if tool_end else 0.08
    if previous in {'效', '効'} and word in {'果', '率', '能', '应', '応'}:
        if word == '果':
            value = 0.42 * old_value if previous == '效' else 1.8
        elif word == '率':
            value = 0.25 * old_value
        else:
            value = 0.15 * old_value if previous == '效' else 0.5
