"""Detect short `ib` fragments, especially the library abbreviation `lib`.

This approximation uses spelling rather than subject matter. Short pieces
ending in ib receive a large negative response; extra letters usually
weaken it. The roots lib, fib, and hib are particularly strong. The productive
inhibit family retains a response in longer words. Common adjectival endings
like -ible and German gib- verb forms are weaker. A one-token memory also
catches the split present participle inhib + iting.
"""
READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('/_.-(').lower()
    index = word.find('ib')
    value = 0.0
    if word.startswith('inhib'):
        value = -3.9 if word == 'inhib' else -2.4
    elif word.startswith('hib') and len(word) > 3:
        value = -2.0
    elif 0 <= index <= 2:
        before, after = word[:index], word[index + 2:]
        if before.endswith('l'):
            strength = 5.8
        elif before in ('f', 'h'):
            strength = 4.3
        elif not before:
            strength = 4.8
        else:
            strength = 2.8
        if len(before) > 1 and before != 'tr':
            strength *= 0.55
        if not after:
            if raw[:1].isspace() and before in ('', 'l', 'b'):
                strength -= 1.6 if not before else 0.8
            if raw.startswith('('):
                strength *= 0.78
            value = -strength
        else:
            value = -strength / (1.0 + 0.85 * len(after))
            if after.startswith(('le', 'ly', 'il')):
                value *= 0.55
            if after == 's':
                value *= 1.25
            if after.startswith('t') or word.startswith('gib'):
                value *= 0.3
    if word == 'iting' and previous == 'inhib':
        value = -2.4
    return (document, word), value

