"""Approximate a written-four detector, including fourth and calendar associations.

ASCII 4 is slightly stronger early in a document and next to letters, and
weaker after an equals sign or numerical punctuation. Number words and other
scripts have their own response sizes. Small responses on unrelated words are
not modeled. No token IDs or learned-model computations are used.
"""
import unicodedata

READS = ()

# Familiar number words and their relatives.
NUMBER_WORDS = {
    'four': 1.29, 'fourth': 1.32, 'fours': 0.69,
    'forty': 0.87, 'fourteen': 0.59,
    'cuatro': 1.18, 'quatro': 1.18, 'quatre': 0.56,
    'vier': 0.82, 'четыре': 1.21,
    'четы': 0.78,  # The beginning of Russian "four".
