    document = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == document else 0
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lstrip('-').lower()
    value = 0.0

    if text == '4':
        previous = prefix.token_strings[-2].strip() if position else ''
        value = 1.055 + 0.20 / (1.0 + position / 16.0)
        if not position:
            value = 1.32
        elif previous.isascii() and previous.isdigit():
            value += 0.03
        elif previous.isalpha():
            value += 0.18
        elif previous.endswith('='):
            value -= 0.19
        elif previous in {'.', ',', ':', '/'}:
            value -= 0.07
    elif text == '四':
        value = 1.59
    elif '四' in text:
        value = 0.95
    elif text == '肆':  # Chinese accounting numeral four.
        value = 0.59
    elif text == '４':
        value = 0.91
    elif text in {'⁴', '₄'}:
        value = 1.80
    elif len(text) == 1 and unicodedata.numeric(text, None) == 4:
        value = 1.0
    elif word in NUMBER_WORDS:
        value = NUMBER_WORDS[word]
        if word in {'four', 'fourth'} and raw.startswith(' ') and text.istitle():
            value += 0.24
        elif word == 'vier' and not raw.startswith(' '):
            value = 0.22
    elif text == 'IV':
        value = 0.48 if raw.startswith(' ') else 0.32
    elif text.lower() == 'iv':
        value = 0.17 if raw.startswith(' ') else 0.09
    elif word == 'april':
        value = 0.67 if raw.startswith(' ') else 0.56
    elif word == 'thursday':
        value = 0.71
    elif text == 'Apr':
        value = 0.14
    elif word in {'quarter', 'quarters', 'quarterly', 'quart'}:
        value = 0.15
    elif '\ufffd' in raw and position:
        # Rare byte-split characters: use only the character completed now.
        end = prefix.text_prefixes[-1][-1:]
        if end in {'⁴', '₄'}:
            value = 1.80
        elif end == '四':
            value = 2.10

    return (document, position), value

