    return re.sub(r"^[^\w一-鿿]+", "", s.strip().lower())


def step(carry, prefix, upstream):
    w = word(prefix.token_strings[-1])
    prev = word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    if w.endswith("pdf"):
        v = PDF
    elif "download" in w or "upload" in w or w in ("下载", "上传"):
        v = TRANSFER
    elif w == "ed" and ("download" in prev or "upload" in prev):
        v = -1.0
    elif w in FORMAT_WORDS:
        v = FORMAT
    elif w in DOC_WORDS:
        v = DOC
    else:
        v = 0.0
    return carry, float(v)

