programs.sol:
"""Lexical equality and comparison markers, not semantic truth.

== and === are strongest, followed by != and !==. Assignments, named equality
predicates, logical connectives, and 'exactly' are weaker. Long runs of equals
are dividers rather than comparisons. Token-fused quotes/brackets and whitespace
modulate the response. Unrecognized tokens receive zero; context is not modeled.
"""
import re

READS = ()
EQUALITY_TESTS = {
    'assertEqual', 'assertEquals', 'isEqualTo', 'EqualTo', 'toEqual',
    'deepEqual', 'toBe', 'AreEqual', 'equalsIgnoreCase', 'PartialEq',
    'strcmp', 'strcasecmp', 'isinstance', 'instanceof',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    s = token.strip()
    value = 0.0
    comparison = re.fullmatch(r'''([()\[\]{}"']*)(!?={2,3}|!=)(["'(\-]?)''', s)
    if comparison:
        left, op, right = comparison.groups()
        if '!' in op:
            value = 4.75 if len(op) == 3 else 4.3
        elif '\n' in token:
            value = 3.5
        elif right in {'"', "'"}:
            value = 5.2
        elif left:
            value = 8.0 if left == '()' else 5.7
        else:
            value = 6.95
            if op == '===':
                value = 7.25 if token.startswith(' ') else 6.65
    elif len(s) >= 4 and set(s) == {'='}:
        value = 4.4 if len(s) <= 6 else (3.5 if len(s) <= 8 else 2.5)
        if len(s) >= 24:
            value = 1.7
        if '\n' in token:
            value *= 0.65
    elif s == '=':
        value = 0.65 if '\n' in token else 0.9
    elif re.fullmatch(r'[)\]}:+*/%&|^<>.\-]=', s):
        value = 1.1
    elif s.startswith('=') and len(s) == 2 and s[-1].isalpha():
        value = 0.43
    elif s in {'=\\', '=`', '=$', '&&'}:
        value = 0.75
    elif s == '||':
        value = 0.48 if token[:1].isspace() else 0.24
    elif s in {'≠', '≡', '≈', '＝'}:
        value = 0.8
    elif s in {'≤', '≥'}:
        value = 0.15
    elif s.lstrip('.') in EQUALITY_TESTS:
        value = 1.7
    elif s in {'.equals', '.Equals', '_EQ'}:
        value = 1.7
    elif s in {'_eq', '.equal', '.Equal'}:
        value = 0.8
    elif s.lower() == 'exactly':
        value = 0.94
    return None, value

programs.luna:
"""Estimate an equality and boolean-check signal from the current token.

Repeated equality signs get stronger predictions than a single equals sign.
Equality assertions, logical connectors, and presence checks get smaller ones.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()

    if "=" in token:
        if "===" in token:
            return None, 7.0
        if "!=" in token:
            return None, 4.1
        if "==" in token:
            return None, 6.7
        return None, 1.0 if token in {"=", ")="} else 0.5

    if token in {"toBe", "assertEquals"}:
        return None, 1.2
    if token in {"exactly", "&&", "||", "hasattr"}:
        return None, 0.5 if token != "exactly" else 0.9
    return None, 0.0

programs.sol:
"""Approximate a local English auxiliary-construction response.

Bare have/do are strongly negative after modals, infinitival to, or
negation; need/want and frequency adverbs are weaker versions. Subjects
following auxiliaries, especially I in "how do I", are also negative.
A two-token context carries the construction across a subject, adverb,
or negation. Smaller rules cover aspect forms, modifiers, thought verbs,
and positive help/sure continuations. Other tokens get zero.

This is a rounded grammatical approximation, not a complete lexical
predictor. State resets at document boundaries.
"""
READS = ()

ABILITY = {'can', 'could'}
FUTURE = {'will', 'would', "'ll", "'d"}
MODAL = {'may', 'might', 'must', 'shall', 'should'}
NEGATIVE = {'not', "'t", 'cannot'}
DO = {'do', 'does', 'did'}
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'been', "'m", "'re", "'s"}
CONDITION = {'if', 'when', 'once', 'before', 'after', 'unless'}
ADVERB = {'also', 'just', 'still', 'already', 'always', 'never', 'only',
          'even', 'now', 'maybe', 'perhaps', 'probably', 'usually',
          'currently', 'sometimes'}

# Neutral amplitude and sensitivity to the preceding grammatical context.
BARE_VERBS = {'have': (-0.30, 2.15), 'do': (-0.07, 1.65),
              'need': (0.13, 1.56), 'want': (-0.16, 1.25)}
FREQUENCY = {'ever': (-0.44, 1.02), 'never': (-0.10, 0.95),
             'always': (-0.08, 1.23)}
READOUT = BARE_VERBS | FREQUENCY
AUXILIARY = ABILITY | FUTURE | MODAL | DO
ASPECT = {'have', 'has', 'had', "'ve"}
MODIFIER = {'also', 'just', 'even', 'probably', 'currently',
            'usually', 'possibly', 'sometimes'}
THOUGHT = {'think', 'know', 'seem', 'feel'}
# Amplitudes after an auxiliary, a clause opener, and in ordinary context.
SUBJECTS = {'I': (-2.6, -0.95, -0.05), 'we': (-1.4, -0.33, 0.08),
            'you': (-0.24, 0.06, 0.0), 'he': (-0.55, -0.15, 0.03),
            'she': (-0.55, -0.15, 0.0), 'they': (-0.55, -0.03, 0.05)}
# Tokenizers can split don't into don + 't, and likewise other negatives.
STEMS = {'don': 'do', 'doesn': 'does', 'didn': 'did', 'won': 'will',
         'wouldn': 'would', 'couldn': 'could', 'shouldn': 'should'}


def strength(word):
    if word in ABILITY: return 1.0
    if word in FUTURE: return 0.79
    if word in MODAL: return 0.54
    if word == 'to': return 0.62
    if word in NEGATIVE: return 0.70
    if word in DO: return 0.41
    if word in BE | ASPECT: return 0.12
    if word in CONDITION: return 0.60
    if word in ADVERB: return 0.44
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1].replace('’', "'")
    word = token.strip().lower()
    value = 0.0
    context = strength(prev)
    if prev in NEGATIVE: context = 0.44 + 0.54 * strength(before)
    if prev in ADVERB: context = 0.26 + 0.56 * strength(before)
    if prev == 'i': context = 0.05 + 0.41 * strength(before)
    if prev in {'we', 'you'}: context = 0.13 + 0.30 * strength(before)
    if prev in {'he', 'she', 'it', 'they'}:
        context = -0.01 + 0.35 * strength(before)
    spelling = token[1:] if token.startswith(' ') else ''
    if spelling in READOUT:
        base, sensitivity = READOUT[word]
        value = base - sensitivity * context
    elif (spelling in SUBJECTS or
          spelling in {'We', 'You', 'He', 'She', 'They'}):
        subject = 'I' if word == 'i' else word
        if subject in SUBJECTS:
            question, clause, ordinary = SUBJECTS[subject]
            value = (question if prev in AUXILIARY else
                     clause if prev in CONDITION | ADVERB else ordinary)
            if prev in BE | ASPECT:
                value = -1.1 if subject == 'I' else -0.2
            if subject == 'I' and prev in FUTURE: value = -2.1
            if subject == 'I' and prev in {'does', 'did'}: value = -1.8
            if subject == 'you' and prev in DO: value = -0.53
            if prev in AUXILIARY and before == 'how':
                value -= 0.7 if subject == 'I' else 0.3
            if (prev in NEGATIVE and before in AUXILIARY and
                subject in {'I', 'we'}):
                value = -1.1
    elif word in {'it', 'this', 'that'} and spelling:
        value = -1.15 if prev in DO else -0.3 if prev in BE | ASPECT else 0.0
    elif spelling in MODIFIER:
        sensitivity = (0.47 if word == 'also' else
                       1.1 if word == 'currently' else 0.8)
        value = 0.03 - sensitivity * context
    elif spelling in THOUGHT:
        value = 0.05 - 0.65 * context
        if prev == 'i': value = 0.13
    elif spelling in {'having', 'doing'}:
        value = (-0.17 if word == 'having' else -0.37) - 0.75 * context
    elif spelling in {'able', 'done'}:
        value = (-0.30 - 0.6 * strength(before) if prev == 'be' else
                 -0.4 if prev in BE | ASPECT | NEGATIVE else -0.15)
    elif spelling in {'has', 'had'}:
        value = (-0.4 if prev in ADVERB else
                 -0.3 if prev in ASPECT else -0.03)
    elif token == "'ve":
        value = -0.1 - 1.9 * context
    elif spelling == 'be':
        value = 0.13 if prev in MODAL else 0.02
    elif spelling == 'help':
        value = 0.9 if prev in NEGATIVE else 0.53 * context
    elif spelling == 'sure':
        value = 0.57 if prev in NEGATIVE else 0.09
    elif word == 'have' and token in {'have', 'Have', ' Have'}:
        value = -0.30 - 1.8 * context
    return (doc, STEMS.get(word, word), prev), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 5033: a negative 'bare verb after a modal' detector.

The component goes negative on the word that comes right after a modal auxiliary
(can, could, will, would, should, may, might, must, do, did, to, not, n't):
  - the verb 'have' there ("will have", "could have", "need to have"): strongest, about -2;
  - the subject 'I' of an inverted question there ("can I", "should I", "do I"): about -2.5;
  - other bare verbs / words there: 'do', 'need', 'want' (about -1); 'that', 'it', 'always',
    'ever', 'never' (about -0.5 to -0.9).
Weaker cases: 'I' after if/when/maybe/perhaps (about -0.9), and 'have' after a
subject pronoun (about -0.6, "we have", "you have"), other 'have' about -0.3.
Everywhere else it is roughly zero.
"""

READS = ()

MODALS = {"can", "could", "will", "would", "should", "may", "might", "must", "shall",
          "to", "do", "does", "did", "cannot", "not", "n't", "'t", "’t", "'ll", "’ll", "never"}
SUBJECT_OPENERS = {"if", "when", "maybe", "perhaps", "whether", "before", "so", "now"}
PRONOUNS = {"you", "we", "i", "they"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    cur = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2]) if len(prefix) > 1 else ""
    if prev in MODALS:
        if cur == "have":
            return carry, -2.0
        if cur == "i":
            return carry, -2.5
        if cur in {"do", "need", "want"}:
            return carry, -1.0
        if cur in {"that", "it", "always", "ever", "never", "happen", "done", "able"}:
            return carry, -0.6
    if cur == "i" and prev in SUBJECT_OPENERS:
        return carry, -0.9
    if cur == "have":
        return carry, -0.6 if prev in PRONOUNS else -0.3
    return carry, 0.0

programs.sol:
"""Approximate a negative word-initial A signal.

Read the current token's spelling and the previous token's ending. A/a
at a word start is negative, especially short capitalized pieces; internal
suffixes are mostly quiet. Familiar grammatical words and phrases weaken
it. Related written A sounds, beginning words, and a few code/chat markers
have separate rules. The training examples motivated treating word starts
differently from suffix fragments such as 'ation'.
"""
import unicodedata

READS = ()
# Frequent grammatical A-words are exceptions to the spelling signal.
# Each row gives a lowercase value and a capitalized value.
FUNCTION_CLASSES = (
    ({'and', 'are', 'also', 'always'}, 0.02, -0.35),
    ({'as', 'at', 'all'}, -0.75, -1.05),
    ({'about', 'above', 'around', 'although', 'away'}, -0.65, -0.65),
    ({'a'}, -1.00, -1.10),
    ({'an'}, -1.14, -1.39),
    ({'after'}, -0.80, -0.80),
    ({'already'}, -0.28, -0.28),
    ({'alternatively'}, -0.68, -0.68),
)


def grammatical_value(word):
    for words, lowercase, capitalized in FUNCTION_CLASSES:
        if word.lower() in words:
            return capitalized if word[0].isupper() else lowercase
    return None

BEGINNINGS = {'first', 'begin', 'began', 'begins', 'beginning', 'primary'}
# Common Mandarin characters whose pinyin begins with A.
PINYIN_A = set(
    '阿啊哎唉哀挨埃癌矮蔼爱碍艾案岸按安暗俺氨'
    '昂盎奥澳懊傲熬敖袄凹愛奧'
)
DELIMITERS = ' \t\r\n./+-([{@\\\"\'`$:=_'


def activation(raw, previous):
    if raw == '</tool_response>':
        return 1.21
    marker = raw.lstrip(" \t\r\n./+-({\\\"'`$:=")
    if marker.startswith(('__', '@')) or marker == '[]':
        return -0.96
    word = raw.lstrip(DELIMITERS)
    if not word:
        return 0.0
    boundary = len(word) != len(raw) or not previous or (
        not previous[-1].isalpha() and previous[-1] != '\ufffd')
    lower, prev = word.lower(), previous.strip().lower()
    if lower in BEGINNINGS:
        return -0.67
    if lower in {'original', 'originally'}:
        return -0.93
    first = word[0]
    base = unicodedata.normalize('NFD', first)[0]
    if base in 'aA':
        if not boundary:
            if lower in {'app', 'api'}:
                return -0.94
            capital_piece = first == 'A' and (
                len(word) == 1 or not word.isupper())
            return -0.45 if capital_piece else -0.06
        if raw.startswith(' '):
            if lower == 'al' and prev == 'et':
                return 0.10
            if lower == 'am':
                return -0.24 if prev == 'i' else -1.20
            if lower == 'as':
                if prev in {'such', 'known'}:
                    return -0.05 if prev == 'such' else -0.20
                if prev in {'well', 'long', 'soon', 'much'}:
                    return -0.38
            if lower == 'at' and prev in {'look', 'looking'}:
                return -0.18
            value = grammatical_value(word)
            if value is not None:
                if lower in {'a', 'an'} and first == 'a':
                    if prev == 'as':
                        value += 0.20
                    elif prev in {'and', 'that', 'if', ',', ':'}:
                        value -= 0.18
                return value
        if base != first:
            return -0.65 if first == 'à' else -1.10
        if lower in {'app', 'api'} and not raw.startswith(' '):
            return -1.90
        if lower == 'a':
            return -1.20 if first == 'a' else -1.25
        if lower in {
            'and', 'are', 'also', 'always', 'already', 'alternatively'
        }:
            return -0.60
        if first == 'A':
            if len(word) == 2:
                return -1.75
            return -1.50 if len(word) < 5 else -1.30
        if not raw.startswith(' '):
            return -1.38 if len(word) < 5 else -1.25
        return -1.12 if len(word) < 5 else -0.98
    if first in 'аА' and boundary:
        return -1.25
    if base in 'αΑ' and boundary:
        return -0.60
    if first == 'あ':
        return -2.35 if len(word) == 1 else -1.05
    if first == 'ア' and previous and not previous.endswith('\ufffd'):
        return -1.25 if boundary or len(word) > 1 else -0.30
    if '\uc544' <= first <= '\uc55f' and boundary:
        return -1.30  # Korean syllables with initial vowel a.
    if first == 'آ' and boundary:
        return -1.50
    if first in PINYIN_A:
        return -2.10 if word in {'阿', '啊'} else -0.90
    return 0.0


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    return (doc, raw), float(activation(raw, previous))

