programs.sol:
"""Local spelling-boundary approximation.

Negative signals mark tokens continuing short h/w onsets, split English
function words, or an h-containing digraph. Short fragments and complete
function words count more than long continuations. Split number words and
'o f' have extra negative signals; o/i vowel continuations are positive.
Initial isolated h/w and o/i letters use the same sign contrast.
The state is just the preceding token, reset at document boundaries.
Standalone NUL tokens are skipped, approximating interleaved zero bytes.
Thai falling-tone marks and chat delimiters have fixed small responses.
These rules capture a few conspicuous responses, not the lexical background.
"""
import math
import re

READS = ()
WORDS = frozenset("""
the this that these those they their there them then thus though
thou thee thy thine who whom whose what when where why which whether
he her here him his how had has have hence
we will with would were was while without within
some such since so shall should she three third through
hither thither whither hence thence whence hereto thereto whereto hitherto
""".split())


def spelling_signal(previous, current):
    match = re.search(r'[A-Za-z]+$', previous)
    stem = match.group().lower() if match else ''
    tail = current.lower()
    # Isolated letters at the start retain the same h/w versus o/i contrast.
    if not previous and tail in ('h', 'w', 'o', 'i'):
        if tail in ('h', 'w'):
            value = -0.309 if tail == 'h' else -0.183
        else:
            value = 0.409 if tail == 'o' else 0.168
        return value * (0.5 if current.isupper() else 1.0)
    if current in ('<|im_start|>', '<|im_end|>'):
        return -0.057
    if current == '้':  # Thai falling-tone mark
        return 0.174
    if stem == 'o' and tail.strip() == 'f':
        return -0.437 if tail == 'f' else -0.55
    if previous.strip().lower() == 'thou' and tail.strip() == 'hast':
        return -0.518
    if not (stem and tail and tail[0].isascii() and tail[0].isalpha()):
        return 0.001

    value = 0.001
    vowel = tail[0] in 'aeiou'
    h = stem in ('h', 'th', 'wh', 'sh', 'ch')
    w = stem.endswith('w') and len(stem) <= 3
    if h:
        value += 0.055 - 0.142 / len(tail) - 0.061 * vowel
    if w:
        value += 0.021 - 0.039 / len(tail) - 0.056 * vowel
    if stem == 'th':
        value -= 0.072
    if stem == 'wh':
        value -= 0.107

    # A function word can begin here even if the token continues further.
    joined = stem + tail
    matches = [word for word in WORDS
               if len(stem) < len(word) and joined.startswith(word)]
    if matches:
        word = max(matches, key=len)
        coverage = (len(word) / len(joined)) ** 2
        value -= (0.198 + 0.091 * h + 0.119 * w) * coverage
        if word == joined:
            value -= 0.022
            if word in ('have', 'has', 'had'):
                value -= 0.276
            if word in ('thou', 'thy', 'thine'):
                value -= 0.195
            if word.startswith('th'):
                value -= 0.197
            if word.startswith('wh'):
                value -= 0.242
        if word == 'whose':
            value -= 0.901

    # A split th/sh/wh/fh, or repeated h; the shortest pieces count most.
    if tail.startswith('h') and stem[-1] in 'sthfw':
        scale = 2 / (len(tail) * math.sqrt(len(stem)))
        value -= (0.066 + 0.544 * tail.startswith('he')) * scale
    if stem in ('tw', 'thr') and tail.startswith('ice'):
        value -= 1.218  # twice / thrice
    if stem == 't' and tail == 'wo':
        value -= 0.902  # two

    if vowel and stem.endswith('o'):
        value += 0.098 if stem == 'o' else 0.037
    if vowel and stem.endswith('i'):
        value += 0.054 if stem == 'i' else 0.006
    if stem.endswith('o') and tail.startswith('b'):
        value += 0.098
    if stem.endswith('o') and tail[0] in 'vf':
        value -= 0.068
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    current = prefix.token_strings[-1]
    if current == '\x00':
        return (doc, previous), 0.001
    return (doc, current), float(spelling_signal(previous, current))

