programs.sol:
"""A lexical detector of 'sub-' and lower or partial units.

Hierarchical parts and subcollections have the strongest response; words like
'subject' and 'subscription' are weaker.  Carry a sub-word across token splits,
with smaller responses on later suffixes and on a following 'of' or 'to'.
Case and punctuation distinguish some word and code forms.  Also recognize
subset signs, below/under words, and selected related Chinese markers.
This captures the dominant lexical pattern, not every small token response.
"""
import re
READS = ()

PREFIXES = {'sub', 'subs', 'subt', 'subst', 'subsequ'}
PARTIAL_ROOTS = PREFIXES | {'substit', 'substr', 'subdiv'}
FAMILIES = (
    (('subseteq',), 1.9),
    (('subclass', 'subtype', 'subsection'), 6.4),
    (('subset', 'subgroup', 'subdiv', 'subspace'), 5.0),
    (('substrate', 'substit'), 1.85),
    (('substring', 'substr', 'subparagraph'), 3.9),
    (('subprocess', 'subsystem', 'sublist', 'subnet', 'subtree',
      'subcommittee', 'subtotal', 'subtitl', 'subtl', 'subdir',
      'subplot', 'submar', 'subspecies'), 3.7),
    (('subscriber',), 2.1),
    (('subject', 'subsequen', 'substance', 'subscrib', 'subscription'), 0.82),
    (('submitted', 'submitting'), 1.8),
    (('submit', 'submission', 'subtract'), 2.48),
