    if word in PREFIXES:
        value += 0.55 if word in ('subs', 'subt') else 0.0
        if not token[0].isspace() and match.group()[0].isupper():
            value += 0.25 if not token.isupper() else -0.35
        if token[0] in '.(':
            value -= 0.5
