            value = 2.4 if word == 'ing' else 2.05
        elif word in ('s', 'es', 'ings') and score >= 3:
            value = 2.05
        else:
            value = 1.23 if score == 2.48 else 0.1
    elif value >= 4.8 and not token[0].isspace():
        value *= 0.52 if word.startswith('subsection') else 0.72
    if not value:
        if word == 'of' and previous:
