                     2.5 if strength(previous) >= 3 else 0.75)
        elif word == 'to' and previous:
            value = 0.97 if strength(previous) == 2.48 else 0.12
        elif word in ('section', 'sections', 'underlying'):
            value = 0.99 if word == 'underlying' else 0.68
        elif (word in ('sous', 'sotto') or
              word.startswith(('undercut', 'undermin', 'undert'))):
