        active = previous
    return (doc, active[-40:]), float(value)

"""A spelling-boundary feature: k/g followed by a vowel versus consonant.

The previous token's ending sets a strength: k/g and counterparts in other
alphabets are strong, c is weak. Vowel-initial continuations are positive,
e/i/y-like starts more than a/o/u-like starts; most consonants are negative.
R/l/h/w are weaker. Spaces and longer continuations suppress the response.
A few spelling adjustments distinguish nasal+velar and doubled-vowel endings.
This approximates spelling, not pronunciation or token-specific magnitudes.
"""
import math
import unicodedata

READS = ()
VELARS = set('kgкгκγكکگغğกง')
EIY_VOWELS = set('eiyıеэиіїыειηυيی')
AOU_VOWELS = set('aouаояуюαοωاو')
THAI_VOWELS = set('ัาำิีึืุูเแโใไ')


def ending_strength(token):
    s = token.lower()
    if s[-1:] == 'c':
        return 0.13
    if not s or s[-1] not in VELARS:
        return 0.0
    if s[-1] in 'κγ':
        return 0.5
    if s.endswith(('ck', 'rk')):
        return 0.7
    if s[-3:-1] in {'aa', 'ee', 'ii', 'oo', 'uu'}:
        return 0.5
    if s.endswith(('ang', 'eng', 'ank', 'enk')):
        return 1.5
    if s[-1] == 'k' and s[-2:-1] in set('aeiou'):
        return 1.25
    return 1.0


def continuation_response(token):
    core = token.lstrip()
    if not core:
        return 0.0
    raw = core[0].lower()
    initial = unicodedata.normalize('NFD', raw)[0]
    vowel = True
    if raw in THAI_VOWELS:
        value = 1.2
    elif initial in EIY_VOWELS:
        value = 1.35
    elif initial in AOU_VOWELS:
        value = 0.89
    else:
        vowel = False
        if core.lower() == 's':  # A lone plural/possessive s is weak.
            value = -0.13
        elif initial in 'kgкг':
            value = -0.75
        elif initial in 'rр':
            value = 0.07
        elif initial in 'lwhлх':
            value = -0.19
        elif initial.isalpha():
            value = -0.53
        else:
            value = 0.0
    decay = 0.30 if vowel else 0.20
    value *= math.exp(-decay * max(0, len(core) - 2))
    if len(core) == 1:
        value *= 1.05
    if core != token:
        value *= 0.04
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous_strength = carry[1] if carry and carry[0] == doc else 0.0
    value = previous_strength * continuation_response(token)
    return (doc, ending_strength(token)), float(value)

