import re

READS = ()
JVM_LIBRARIES = frozenset(
    'apache junit testng hibernate vaadin lombok slf poi nio jackson '
    'mockito bukkit alibaba kafka commons'.split()
)
SPRING_PACKAGES = frozenset(
    'beans factory stereotype boot web servlet annotation repository '
    'autoconfigure configuration security jdbc'.split()
)
SPRING_ANNOTATIONS = frozenset(
    'Autowired Repository Controller Service Component Configuration Bean '
    'ResponseBody RequestParam PathVariable Slf'.split()
)
JAVA_TYPE_ENDINGS = (
    'Factory', 'Configurer', 'Interceptor', 'Configuration', 'Annotation',
    'Repository', 'Exception', 'Writer', 'Iterable', 'Strategy', 'Dao',
)


def response(token, before):
    text = token.strip()
    name = text.lstrip('.@/("')
    if text in {'me', "'s", '’s'} and re.search(r'\blet\s*$', before, re.I):
        return 0.87
    if text == 'us' and re.search(r'\blet\s*$', before, re.I):
        return 0.60
    if text.lower() == 'wait':
        return 0.42
    if text == '／':
        return 0.50
    if text == '}{':
        return 0.33
    if text.count('/') == 1 and all(c in '/()>{}."\'' for c in text):
        if token.startswith(' ') and text == '/':
            return 0.48
        if text == '/' and before.rstrip()[-1:].isdigit():
            return 0.39
        return 0.26
    if text in {'@', ',@', '(@', '{@'}:
        return 0.40
    if name.lower() == 'springframework':
        return 3.2
    if text.startswith('.') and 'springframework' in before[-100:]:
        if name in SPRING_PACKAGES:
            return 3.0
        if name in {'context', 'core', 'jpa'}:
            return 2.6
    if text in {'.servlet', '.stereotype'}:
        return 3.1
    if name in JVM_LIBRARIES and (
        text.startswith(('.', '/')) or name == 'lombok'
    ):
        return 1.9
    if name in {'groupId', 'artifactId', 'artifact'} and before.endswith('<'):
        return 1.9
    if name == 'org':
        if text.startswith('.'):
            return 0.34
        if token[:1].isspace() or text.startswith('/'):
            return 0.98
        return 0.0
    if name == 'java' and (
        token[:1].isspace() or text.startswith(('.', '/'))
    ):
        return 0.58
    if name in {'RequestMapping', 'GetMapping', 'PostMapping', 'PutMapping',
                'DeleteMapping', 'PatchMapping'}:
        return 3.2
    if name.startswith(('Enable', 'ConditionalOn')) and (
        text.startswith(('@', '.')) or before.rstrip().endswith('@')
    ):
        return 2.5
    if name in SPRING_ANNOTATIONS and (
        text.startswith(('@', '.')) or before.rstrip().endswith('@')
    ):
        return 1.7
    if name == 'Override' and not token[:1].isspace():
        return 1.0
    if name.endswith(JAVA_TYPE_ENDINGS) and name[:1].isupper():
        if (not token[:1].isspace() or re.search(r'[a-z][A-Z]', name)
                or name.endswith('Exception')):
