"""Partial spelling-based predictor of a negative nasal-cluster response.

Short n+consonant fragments near a token's beginning receive negative
pulses. Following letters, digraphs (nch/nth/nsch), whitespace and case
adjust their strength; ordinary closed endings like -ing stay weak.
Short Arabic, Cyrillic and kana nasal clusters have analogous rules.
Two local contexts distinguish ordinals and literal escaped newlines.

These are calibrated spelling categories, not a pronunciation parser.
There is no token-id or whole-word lookup. Most lexical and longer-context
variation is deliberately left unexplained.
"""
import re
import unicodedata

READS = ()
CONSONANTS = 'bcdfghjklmpqrstvwxyz'
VOWELS = frozenset('aeiouy')


def token_response(token):
    raw = token.strip()
    lower = raw.lower()
    word = ''.join(c for c in unicodedata.normalize('NFKD', lower)
                   if not unicodedata.combining(c))

    # Short nasal + consonant clusters in other writing systems.
    if re.search('ن[بتجحخدذرزسشصضطظعغفقكلمنه]', raw):
        if len(raw) <= 2:
            return -1.85 if raw.startswith('نج') else -0.55
        return -0.12
    if re.search('[ンん][トドグクタダジチバパブプとどぐくただじちばぱぶぷ]', raw):
        return -0.52 if len(raw) <= 2 else -0.10
    if re.search('н[бвгджзклмнпрстфхцчшщ]', lower) and len(raw) <= 3:
        return -0.30

    match = re.search('n[' + CONSONANTS + ']', word)
    if not match:
        return 0.003
    p = match.start()
    consonant = word[p + 1]
    tail = word[p + 2:]
    digraph = (consonant in 'ct' and tail.startswith('h') or
               consonant == 's' and tail.startswith('ch'))
    # Position is measured within the stripped token, not the full word.
    if p == 0:
        return -0.63 if tail.startswith('e') else -0.28
    if p == 1:
        # n+dr before a short following syllable, including names.
        if consonant == 'd' and tail.startswith('r') and len(tail) <= 3:
            return -0.45 if not token[:1].isspace() or raw.istitle() else -0.15
        if digraph:
            if token[:1].isspace():
                return -0.30
            return -0.95 if len(tail) <= 2 else -0.33
        if token[:1].isspace():
            if tail == 'er':
                return -0.11
            return -0.005 if raw.islower() else -0.05
        # Closed endings are usually quiet; unusual pairings are stronger.
        if not tail:
            if consonant in 'fvhz':
                return -0.60 if word[0] == 'a' else -0.26
            if word != lower:
                return -0.32
            return -0.26 if consonant in 'kqj' else -0.015
        if not raw.islower():
            return -0.04
        # Short extended fragments differ from ordinary closed endings.
        if consonant == 'c':
            return -0.09
        if tail == 's':
            return -0.06
        if len(tail) <= 2:
            if consonant == 'g':
                if tail == 'er':
                    return -1.02
                if all(c in VOWELS for c in tail):
                    return -0.74
                return -0.58 if word[0] == 'i' else -0.22
            if consonant in 'kqj':
                return -0.64
            if tail == 'on':
                return -0.73
            if tail.startswith('u'):
                return -0.02
            if tail == 'o':
                return -0.22
            return -0.28 if word[0] == 'e' else -0.41
        n_consonants = sum(c in CONSONANTS or c == 'n' for c in tail)
        return -0.04 if n_consonants >= 3 else -0.22
    if p == 2:
        if consonant == 'g' and word[1] == 'i' and tail.startswith('er'):
            return -0.40 if token[:1].isspace() and raw.islower() else -0.60
        if consonant == 'c' and digraph:
            return -0.27
        if tail == 'e' and consonant != 'c':
            return -0.14
        return -0.008
    return 0.005


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = token_response(token)
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
        if token == 'nd' and previous[-1:].isdigit():
            value = -0.055  # An ordinal ending, not an internal word fragment.
        if (previous.endswith('\\') and token.startswith('n') and
                len(token) > 1 and token[1].isupper()):
            value = -0.60  # Literal escaped newline fused to the next word.
    return None, float(value)

programs.luna:
"""A compact spelling-based proxy for the component's sparse responses.

In order, it scores 'ang' and 'ant' clusters negatively, other n+consonant
clusters a little less negatively, and n-ending or other n-containing spellings
slightly positively. Other tokens receive zero.
"""

READS = ()


def step(carry, prefix, upstream):
    spelling = prefix.token_strings[-1].casefold().strip()
    if "ang" in spelling:
        return None, -0.0336
    if "ant" in spelling:
        return None, -0.0379
    for left, right in zip(spelling, spelling[1:]):
        if left == "n" and right.isalpha() and right not in "aeiou":
            return None, -0.0132
    if spelling.endswith("n"):
        return None, 0.0103
    if "n" in spelling:
        return None, 0.0097
    return None, 0.0

