    "frequently": -3.0, "daily": -2.2, "often": -1.5, "usually": -1.3, "normally": -1.3,
    "weekly": -1.6, "monthly": -1.7, "occasionally": -2.0, "whenever": -1.1,
    "sometimes": -0.7, "commonly": -0.8, "typically": -0.5, "rarely": -0.5,
