NORMAL = {"usual": -1.9, "normal": -1.5, "ordinary": -1.0, "typical": -0.5, "special": -1.0,
          "basis": -1.4, "popular": -0.9, "extra": -0.8, "average": -0.4, "common": -0.25}
CHINESE = {"常": -4.0, "常常": -3.3, "每天": -1.8, "定期": -3.0, "时常": -2.6, "每": -0.9}
