"""A detector of typographical full-stop boundaries, not grammatical sentences.

Separate spaces and space-led line breaks after a period get large negative
values, including after abbreviations and list numbers. Quotes, parentheses,
other sentence-ending marks, and subsequent indentation get weaker values.
The response is stronger near a document's beginning. Repeated dots can give
positive values. Ordinary word tokens get zero; their small lexical variations
are deliberately omitted. State resets when the document changes.
"""
from math import exp

READS = ()
QUOTES_AND_BRACKETS = '\"\'”’“‘«»「」『』）)]}'
SPACE_LED_SEPARATORS = {
    '(': -1.85,
    '[': -1.4,
    '"': -0.96,
    '“': -0.75,
    '-': -1.2,
    '–': -1.2,
    '—': -1.2,
    '\\': -1.7,
    '»': -1.7,
}


def boundary_strength(text):
    bare = text.rstrip('\\')
    core = bare.rstrip(QUOTES_AND_BRACKETS)
    if core.endswith(('。', '．')):
        return 1.0
    if core.endswith('.'):
        if core.endswith('..'):
            return 0.52
        return 0.7 if core != bare else 1.0
    if core.endswith(('?', '？', '؟')):
        return 0.65
    if core.endswith(('!', '！')):
        return 0.56
    return 0.55 if core.endswith('…') else 0.0


def separator_value(text):
    if text.isspace():
        if '\n' in text:
            lines = text.count('\n')
            if text.startswith(' '):
                return -3.45 if lines == 1 else -2.85
            return -1.9 if lines == 1 else -2.4 if lines == 2 else -1.65
        if text == ' ':
            return -2.02
        if text == '\u00a0':
            return -1.9
        if '\t' in text:
            return -2.45
        return -2.55 if len(text) <= 4 and not text.strip(' ') else -1.6
    if text == '<|im_end|>':
        return -1.18
    if text.startswith(' '):
        symbol = text.lstrip(' ')
        if symbol[:1] in SPACE_LED_SEPARATORS:
            return SPACE_LED_SEPARATORS[symbol[0]]
        if not symbol.strip('.…'):
            return 0.6 if len(symbol) > 3 else 0.8 + 0.25 * (len(symbol) - 1)
        if '�' in symbol:
            return -0.35
        if not any(c.isalnum() for c in symbol):
            return -0.6
    if text.startswith(('-', '*')):
        return -1.4
    if not any(c.isalnum() for c in text):
        return -1.8 if text.startswith(('」', '』')) else -0.85
    return 0.0


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, earlier, position = '', '', 0
    else:
        _, previous, earlier, position = carry
        position += 1
    strength = boundary_strength(previous)
    core = previous.rstrip(QUOTES_AND_BRACKETS)
    value = strength * separator_value(text)

    # Bare newlines differ from the stronger space-led line-break tokens.
    if strength and text.isspace() and '\n' in text:
        if not text.startswith(' '):
            value = separator_value(text) * (0.8 if strength == 0.52 else 1.0)
    if core.endswith((':', ';')) and text.isspace():
        value = -0.5 if '\n' in text else -0.12
    if previous == ' .' and text.isspace() and '\n' in text:
        value *= 0.71
    if '.\n' in previous or '.\r' in previous:
        value = 0.3 * separator_value(text)
    if core.endswith(('。', '．')):
        if text == ' ':
            value = -2.7
        elif text.startswith(' ') and '�' in text:
            value = -1.7  # Byte fragment after an ideographic stop.

    # A boundary can span a quote, an escape, or a line/chat delimiter.
    if previous and not previous.strip(QUOTES_AND_BRACKETS) and text.isspace():
        value = 0.75 * boundary_strength(earlier) * separator_value(text)
    if previous.endswith('\\') and text == 'n':
        value = -0.74 * strength
    if previous == '<|im_end|>' and text == '\n':
        value = -1.28 * boundary_strength(earlier)
    if previous.isspace() and '\n' in previous and text.isspace():
        if len(text) >= 3 and '\n' not in text:
            value = -0.5 * boundary_strength(earlier)

    if previous.endswith('.') and value < -0.6:
        value *= 0.965 + 0.276 * exp(-position / 64.0)
    if previous == ' .' and text == ' .':
        value = 0.45
    if text and not text.strip('·') and not previous.strip('·'):
        value = 0.53
    return (doc, text, previous, position), float(value)

"""A local spelling detector for FORM and its relatives.

Bare FORM is strongest; its longer derivatives and compounds are weaker.
Capitalization and attachment to other text affect the magnitude. The signal
can continue into a suffix or the following 'of'. Cyrillic form/norm and
Chinese form/format words have parallel responses. Shape words are weaker
still. Unmatched tokens get zero.
"""
READS = ()


def response(token):
    word = token.strip().lstrip("._/(-=<>\\\\")
    low = word.lower()
    joined = not token[:1].isspace()
    capital = word[:1].isupper()
