        if capital:
            return 6.3 if low == 'form' else 5.5
        if token.startswith('-'):
            return 7.4
        return 6.2 if joined else 4.8
    if low in ('iform', 'orm', 'ormal'):
        return 7.3 if low == 'iform' else (3.9 if low == 'orm' else 2.0)
    # Formation must precede format: they share their first six letters.
    if low.startswith('formation'):
        return 2.6
    if low.startswith('former'):
        return 1.2 if low.endswith('ly') else 2.1
    if low.startswith(('formal', 'format', 'formed', 'forming')):
        if low.startswith(('formatting', 'formatted', 'formatter')):
            return 2.3
        return 3.8
    if low.startswith(('forma', 'forme', 'formul')):
        return 1.4 if low in ('formula', 'formulas', 'formerly') else 2.6
    if low.startswith('form') and len(word) > 4 and word[4].isupper():
        return 3.3
    if low.startswith(('reform', 'conform', 'deform', 'transform', 'inform')):
        if low in ('reform', 'reforms'):
            return 5.2 if low == 'reform' else 3.9
        if low == 'conform':
            return 3.6
        if low.startswith(('information', 'informaci', 'informaç')):
            return 0.0
        return 2.0 if low in ('deform', 'transform', 'inform') else 1.2
    if low.startswith(('normal', 'uniform')) or low == 'fmt':
        if low.endswith('ly'):
            return 0.6
        return 1.0 if low != 'fmt' else 1.8
    if low in ('norm', 'norms'):
        return 2.8 if capital else 2.0
    if 'форм' in low and not low.startswith('информа'):
        if low.startswith('информ'):
            return 1.5
        return 5.4 if low == 'форм' and joined else 3.4
    if low == 'орм' or low.startswith('норм'):
        return 1.8
    if word in ('形式', '的形式'):
        return 4.3
    if word in ('格式', '正式', '改革') or '形成' in word:
        return 2.6
    if word in ('形', '式', '公式', '形态', '形態'):
        return 1.4
    if word in ('型', '成') or 'morph' in low:
