        value += 1.6 if prev in ('form', 'reform') else 1.3
    if prev in ('form', 'reform', 'conform', 'iform'):
        strength = response(previous)
        if low in ('ing', 'ed', 's', 'ally'):
            value += 0.5 * strength
        elif low in ('er', 'ers', 'en', 'e', 'a', 'as', 'ats', 'ations', 'atted'):
            value += 0.27 * strength
        elif low in ('al', 'is', 'es', 'ity', 'an', 'ula'):
            value += 0.14 * strength
    if low in ('form', 'forms', 'formed', 'forming', 'iform', 'formation'):
        if prev in ('per', 'outper'):
            value *= 0.25
        elif low == 'iform' and prev == 'un':
            value = 3.4
        elif prev in ('plat', 'platt', 'plate', 'plata', 'att', 'trans', 'tras'):
            value *= 0.5
        elif prev in ('in', 'con', 'de', 'wave'):
            value *= 0.6 if low == 'form' else 0.8
        elif prev in ('re', 'pre', 'free') and low in ('formed', 'formation'):
            value *= 1.35
    return (doc, token), float(value)

