"""Predict local spelling and formatting cues, not the full lexical response.

Word pieces after short O-containing fragments get positive pulses, larger
for consonant continuations and near document beginnings. Japanese O-row
kana (except common particles) and Korean O syllables are related cues.
Thinking/tool delimiters and their blank lines get signed pulses. There is
also a negative special case for the initial two tokens spelling "12".
This deliberately omits the component's much larger lexical variation.
"""
import re
import math

READS = ()
VOWELS = set('aeiouyаеиоуыэюяё')
O_HIRAGANA = set('おぉこごそぞとどのほぼぽもよょろ')
O_KATAKANA = set('オォコゴソゾトドノホボポモヨョロ')
PARTICLES = set('のとも')
CONTROLS = {
    '<think>': -0.025, '</think>': -0.077,
    '<tool_call>': -0.026, '</tool_call>': -0.005,
    '<tool_response>': -0.075, '</tool_response>': 0.045,
    '<|im_end|>': 0.013, '<|endoftext|>': 0.009,
}


def o_continuation(previous, token):
    if not token[:1].isalpha():
        return 0.0
    match = re.search(r'[^\W\d_]+$', previous.lower())
    stem = match[0] if match else ''
    n = len(stem)
    consonant = token[0].lower() not in VOWELS
    o = max(stem.rfind('o'), stem.rfind('о'))
    if o >= 0 and n <= 4:
        tail = n - o - 1
        if n == 1:
            return 0.047 if consonant else 0.012
        if tail == 0:
            return 0.0 if consonant else -0.008
        if tail == 1:
            value = 0.136 - 0.028 * n
            if not consonant:
                value = max(0.0, 0.084 - 0.021 * n)
            elif previous[-1:].lower() == token[0].lower():
                value += 0.035
            return value
        return 0.028 if consonant else 0.0
    if n == 1:
        if stem in {'お', 'オ', 'ぉ', 'ォ'}:
            return 0.11
        if stem in PARTICLES:
            return -0.008
        if stem in O_HIRAGANA or stem in O_KATAKANA:
            return 0.045
        code = ord(stem)
        if 0xAC00 <= code <= 0xD7A3:
            syllable = code - 0xAC00
            vowel = syllable // 28 % 21
            initial = syllable // 588
            # Hangul vowel 8 is O; initial 11 is the silent consonant ㅇ.
            if vowel == 8:
                return 0.20 if initial == 11 else 0.045
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    token = prefix.token_strings[-1]
    value = o_continuation(previous, token)
    value *= 0.9 + 0.8 / math.sqrt(max(1, position))
    if token in CONTROLS:
        value = CONTROLS[token]
        if token == '<|im_end|>' and previous == '</tool_call>':
            value = -0.004
        elif token == '<|im_end|>' and previous == '</tool_response>':
            value = 0.020
    elif token == '<|im_start|>':
        value = 0.034 if position == 0 else -0.002
    elif token == '\n\n':
        if previous == '</think>':
            value = 0.118
        elif previous == '<think>':
            value = 0.060
        else:
            value = 0.004
    elif token == '\n':
        value = 0.008 if previous == '<|im_end|>' else 0.002
    elif position == 1 and previous == '1' and token == '2':
        value = -0.073
    return (doc, token, position), float(value)

"""Detect notation introducers, especially a dollar followed by a TeX
backslash. Smaller cues are dollar-prefixed expressions, opening braces
before quotes/backslashes, TeX/escape introducers, and the display command
fragment after a backslash. For isolated cues, preceding punctuation and
recently escaped code lines adjust the
response; state resets at document boundaries. Ordinary text and most
completed escapes receive zero. Word-specific variation outside these cues
is omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, prev = ('', '') if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    b, p = s.lstrip(), prev.rstrip()
    spaced = s.startswith(' ')
    encoded = '\\n' in tail or '\\t' in tail
    code = '->' in tail or '$_' in tail or '<?php' in tail
    v = 0.0
    if b == '$\\':
        v = 3.29 if prev else 5.77
    elif '\\$' in b:
        v = 1.1 if spaced else 0.9
    elif b.endswith('{\\'):
        v = 0.63 if spaced else 1.1
    elif b == '\\':
        v = 0.3 if spaced else 0.4
        if not prev:
            v = 0.71 if spaced else 1.07
        elif p.endswith('$'):
            v = 1.06
        elif p and (p[-1].isdigit() or p[-1] in '=+-*({[|'):
            v = 0.34 if spaced else 0.6
        elif p.endswith(('.', ',', ';', ':', ')', '}', ']')):
            v = 0.0 if encoded else 0.2
        elif '\n' in prev:
            v = 0.4 if spaced else 0.6
        elif encoded:
            v = 0.0 if spaced else -0.05
    elif b.endswith('\\'):
        stem = b[:-1]
        if stem in ('(', '[', '|'):
            v = 0.35 if encoded else 0.8
        elif stem in ('=', '+', '-', '*', '^', '_'):
            v = 0.46
        elif stem in ('}', ']'):
            v = 0.44 if spaced else 0.3
        elif stem.endswith('"'):
            v = 0.28 if stem.startswith('\\') else 0.55
    elif b == '\\(':
        v = 0.86
    elif b == '$':
        v = 1.0 if spaced else 0.15
        if not prev:
            v = 1.15 if spaced else 0.68
        elif '\n' in prev:
            v = 0.85
        elif code or prev.isspace() or p.endswith(('=', '(', ')', '}', ']')):
            v = 0.25
        elif prev.strip() in ('return', 'echo', 'print'):
            v = 0.22
        elif p and p[-1].isdigit():
            v = 0.43 if spaced else 0.13
        elif p.endswith(('.', ',', ';', ':')):
            v = 0.60 if spaced else 0.35
    elif b in ('${', '$_'):
        v = 1.1 if b == '${' else 1.5
    elif b.startswith('$('):
        v = 1.0 if spaced else 0.72
    elif '${' in b or '$_' in b:
        v = 0.73
    elif b == '$$' and spaced:
        v = 0.37
    elif b != '$$' and b.endswith('$') and not b.endswith((')$', '}$', ']$')):
        v = 0.43
    elif b == 'display' and prev.endswith('\\'):
        v = 0.75 if '$\\' in prev else 0.25
    elif '{"' in b or "{'" in b:
        v = 0.52 if spaced else 0.47
    return (doc, (tail + s)[-80:], s), float(v)

