"""Estimate a rare syntax-opening signal from the newest token.

The examples point to math delimiters, escapes, and code/template openers;
ordinary words do not get a contribution.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip()

    # A dollar followed by a TeX escape starts a particularly strong pattern.
    if token.startswith("$\\"):
        return None, 2.5

    # Inline math and TeX command boundaries.
    if token.startswith("\\(") or token.startswith("{\\"):
        return None, 0.8
    if token.startswith("\\"):
        return None, 0.45

    # Code interpolation and JSON-like object syntax.
    if token.startswith("${") or token.startswith("($") or token.startswith("{\""):
        return None, 0.65
    if token.startswith("$"):
        return None, 0.8

    return None, 0.0

