    elif word in {'constraint', 'constraints'}:
        value = 1.72 if capitalized and not spaced else 1.39
    elif word in {'constrain', 'constrained'}:
        value = 0.44 if word == 'constrain' else 0.77
    elif word in {'coefficient', 'coefficients'}:
        value = 0.66 if word.endswith('s') else 0.55
    elif word == 'maybe':
