    elif word in SIZE_ADJECTIVES:
        value = SIZE_ADJECTIVES[word]
        if word == 'huge' and not spaced:
            value = -0.42
    elif spelling == 'TODO':
        value = -0.81 if spaced else -0.56
    elif word in PERSON_PRONOUNS:
        value = PERSON_PRONOUNS[word]
        if capitalized and word != 'anybody':
            value = -0.45 if word == 'nobody' else -0.40
    elif word == 'middleware':
        value = 0.45 if not capitalized else 0.28
    return None, value

programs.luna:
"""A sparse word cue for the component's clearest responses.

It gives a positive pulse to the word forms “command” and “constraint,” and
an opposing pulse to “maybe.” These are the repeated, strong lexical cues in
the sampled high-impact contexts; other tokens receive zero.
"""
READS = ()

POSITIVE = {"command", "commands", "constraint", "constraints"}
NEGATIVE = {"maybe"}


def step(carry, prefix, upstream):
    word = "".join(ch for ch in prefix.token_strings[-1].lower() if ch.isalpha())
    if word in POSITIVE:
        return None, 1.0
    if word in NEGATIVE:
        return None, -1.3
    return None, 0.0

"""Predict the component's large response to chat and tool-control tokens."""

READS = ()

CONTROL_VALUES = {
    "<|im_end|>": -1.63,
    "<|im_start|>": -1.47,
    "<tool_call>": -1.55,
    "</tool_call>": -1.06,
    "<tool_response>": -0.60,
    "</tool_response>": -1.12,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    return None, CONTROL_VALUES.get(token, 0.0)

programs.sol:
"""A lexical detector of importance, personal matters, and social description.

'Personal' and 'important' dominate. Related word forms and a few translations
produce smaller responses. 'Out' depends on its preceding verb: 'turn out'
and 'stand out' are positive, whereas 'take out' and 'come out' are negative.
Capitalized and unspaced forms of the strongest words are weaker. This
approximation deliberately leaves the diffuse response to other words at zero.
"""

READS = ()

SIGNIFICANCE = {
    'importance': 0.23, 'importantly': 0.23,
    'vital': 0.27, 'serious': 0.21, 'crucial': 0.20,
    'powerful': 0.21, 'essential': 0.13, 'critical': 0.10,
    'necessary': 0.075,
}
PEOPLE = {
    'person': 0.11, 'persons': 0.10, 'personality': 0.11,
    'individual': 0.18, 'individuals': 0.10, 'individually': 0.085,
    'personalize': 0.40, 'personalized': 0.28, 'personalised': 0.25,
    'human': 0.07, 'social': 0.19, 'professional': 0.10,
    'political': 0.15, 'national': 0.12, 'local': 0.11,
    'economic': 0.09, 'international': 0.10,
}
TRANSLATIONS = {
    'importante': 0.36, 'wichtig': 0.35, 'важ': 0.31, 'важно': 0.16,
    '重要': 0.40, '重要的': 0.29, '的重要': 0.34, '重要な': 0.28,
    '大事': 0.40, '个人': 0.52, '個人': 0.41,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()

    if lower == 'personal':
        value = 1.08 if word == 'personal' and token.startswith(' ') else 0.90
        if token == 'personal':
            value = 0.75
    elif lower == 'important':
        value = 0.81 if word == 'important' and token.startswith(' ') else 0.54
        if token == 'important':
            value = 0.55
        if word.isupper():
            value = 0.28
    elif lower == 'personally':
        value = 0.54 if word.islower() else 0.46
    elif word in TRANSLATIONS:
        value = TRANSLATIONS[word]
    elif word in SIGNIFICANCE:
        value = SIGNIFICANCE[word]
    elif word in PEOPLE:
        value = PEOPLE[word]
    elif token == ' out':
        if previous in {'turn', 'turns', 'turned', 'turning'}:
            value = 0.50
        elif previous in {'stand', 'stands', 'standing', 'stood'}:
            value = 0.31
        elif previous in {'point', 'points', 'pointed', 'pointing'}:
            value = 0.21
        elif previous in {'take', 'takes', 'taking', 'taken', 'took'}:
            value = -0.21
        elif previous in {'come', 'comes', 'coming', 'came'}:
            value = -0.13
        elif previous in {'carry', 'carries', 'carried', 'carrying', 'check'}:
            value = 0.08
        else:
            value = 0.03
    else:
        value = 0.0

    return (doc, lower), value

programs.luna:
"""Predict sparse positive responses on importance and personal words.

The harvest's biggest examples are “important” and “personal”; it also
shows the related noun “importance”, Chinese and Portuguese words, one
“social”, and “out” after a form of “turn”.  Most other tokens get no
prediction.
"""

READS = ()

IMPORTANCE_WORDS = {
    "important": 0.76,
    "importance": 0.19,
    "重要": 0.45,
    "importante": 0.34,
}
PERSONAL_WORDS = {
    "personal": 1.05,
    "personally": 0.41,
    "個人": 0.40,
}
TURN_FORMS = {"turn", "turns", "turned", "turning"}


def clean(text):
    return text.strip().lower().strip(".,:;!?\"'()[]{}")


def step(carry, prefix, upstream):
    word = clean(prefix.token_strings[-1])
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""

    value = IMPORTANCE_WORDS.get(word, PERSONAL_WORDS.get(word, 0.0))
    if word == "social":
        value = 0.36
    if word == "out" and previous in TURN_FORMS:
        value = 0.44

    return (doc, word), float(value)
